/**
 * 1. Creates a custom URL structure for artist profiles.
 * Example: artmatter.co/artist/username/
 */
function add_artist_profile_rewrite_rule() {
    add_rewrite_rule(
        '^artist/([^/]+)/?$',
        'index.php?author_name=$matches[1]',
        'top'
    );
}
add_action('init', 'add_artist_profile_rewrite_rule');


/**
 * 2. Force 404 if the requested user is NOT an artist.
 */
function restrict_artist_profile_access($query) {
    // Only run on front-end main query
    if ( ! is_admin() && $query->is_main_query() && $query->get('author_name') ) {

        $username = $query->get('author_name');
        $user = get_user_by('login', $username);

        // If no user found → 404
        if ( ! $user ) {
            $query->set_404();
            return;
        }

        // Check if the user has the 'artist' role
        if ( ! in_array('artist', (array) $user->roles, true) ) {
            // Not an artist → treat as 404
            $query->set_404();
        }
    }
}
add_action('pre_get_posts', 'restrict_artist_profile_access');


/**
 * 3. Change the browser tab <title> for Artist profiles (RankMath Compatible).
 * This overrides RankMath's author SEO settings.
 */
add_filter( 'rank_math/frontend/title', 'artmatter_rankmath_artist_title' );

function artmatter_rankmath_artist_title( $title ) {
    if ( is_author() ) {
        $author = get_queried_object();
        
        if ( $author instanceof WP_User && in_array('artist', (array) $author->roles, true) ) {
            // Fetch the custom meta field
            $custom_name = get_user_meta( $author->ID, 'artist_display_name', true );
            
            // Extract from array if ACF/Pro Forms saved it that way
            if ( is_array( $custom_name ) && ! empty( $custom_name ) ) {
                $custom_name = $custom_name[0];
            }
            
            $display_name = ! empty( $custom_name ) ? $custom_name : $author->display_name;
            
            // Build the title mimicking standard SEO format: "Artworks by Name - Site Name"
            $site_name = get_bloginfo( 'name' );
            return 'Artworks by ' . $display_name . ' - ' . $site_name;
        }
    }
    return $title;
}


/**
 * 4. Change the on-page <h1> title for Artist profiles.
 * Includes the array fix so it prints the text correctly.
 */
add_filter( 'get_the_archive_title', 'artmatter_artist_h1_title', 20 ); // Priority 20 to ensure it runs last

function artmatter_artist_h1_title( $title ) {
    if ( is_author() ) {
        $author = get_queried_object();
        
        if ( $author instanceof WP_User && in_array('artist', (array) $author->roles, true) ) {
            // Fetch the custom meta field
            $custom_name = get_user_meta( $author->ID, 'artist_display_name', true );
            
            // Extract from array
            if ( is_array( $custom_name ) && ! empty( $custom_name ) ) {
                $custom_name = $custom_name[0];
            }
            
            $display_name = ! empty( $custom_name ) ? $custom_name : $author->display_name;
            
            // Completely replace the default string
            $title = 'Artworks by ' . $display_name;
        }
    }
    return $title;
}

/**
 * ============================================================
 * ART_FANDOM TERM META SYNC (Bulletproof Version)
 * ============================================================
 */
function artmatter_final_fandom_sync( $term_id, $tt_id, $taxonomy ) {

    // 1. Double check taxonomy
    if ( $taxonomy !== 'art_fandom' ) {
        return;
    }

    /**
     * 2. The "Nuclear" Cache Clear
     * We force WP to forget the cached term data and pull 
     * fresh from the database to get the real Slug and Name.
     */
    clean_term_cache( $term_id, $taxonomy );
    $term = get_term( $term_id, $taxonomy );

    if ( ! $term || is_wp_error( $term ) ) {
        return;
    }

    // 3. The ACF Target ID (Must match the new taxonomy name)
    $acf_id = 'art_fandom_' . $term_id;

    /**
     * 4. Update Fields
     * Note: If 'fandom_title' (the name) doesn't work, 
     * use the Field Key (e.g. 'field_123456') instead.
     */
    update_field( 'fandom_title', $term->name, $acf_id );
    update_field( 'fandom_slug',  $term->slug, $acf_id );

    $link = get_term_link( $term );
    if ( ! is_wp_error( $link ) ) {
        update_field( 'fandom_public_url', $link, $acf_id );
    }
}

