//REDIRECT WP-LOGIN.PHP but still safe for logging out & nextend social login
function redirect_login_page() {
    $login_page = home_url( '/login/' ); // Your custom login page
    $page_viewed = basename($_SERVER['REQUEST_URI']);

    // Redirect to the custom login page if accessing wp-login.php directly via GET request
    if ($page_viewed == "wp-login.php" && $_SERVER['REQUEST_METHOD'] == 'GET') {
        wp_redirect($login_page);
        exit();
    }
}
