/**
 * Artmatter "Cloud-First" Artwork Processor
 * * FEATURES:
 * 1. Uploads Master to R2 and IMMEDIATELY DELETES local copy (Zero Storage).
 * 2. Renames files directly on R2 (Copy+Delete) when Product Title changes.
 * 3. Keeps your server clean.
 */

/* ---------------------------------------------------------------------------
   PART 1: R2 HELPER (Now with Cloud-Side Copy)
   --------------------------------------------------------------------------- */
if ( ! class_exists( 'Artmatter_R2' ) ) {

    class Artmatter_R2 {
        
        // --- 1. UPLOAD (Standard) ---
        public static function upload_file( $local_path, $remote_key ) {
            if ( ! file_exists( $local_path ) ) return false;
            // Windows fix
            clearstatcache( true, $local_path ); usleep( 100000 );

            $account_id = AM_R2_ACCOUNT_ID;
            $bucket     = AM_R2_BUCKET;
            $access_key = AM_R2_ACCESS_KEY;
            $secret_key = AM_R2_SECRET_KEY;

            // Clean Key
            $remote_key = ltrim( str_replace( '\\', '/', $remote_key ), '/' );
            $encoded_key = implode( '/', array_map( 'rawurlencode', explode( '/', $remote_key ) ) );

            $host = "{$account_id}.r2.cloudflarestorage.com";
            $uri  = "/{$bucket}/{$encoded_key}";
            $url  = "https://{$host}{$uri}";

            $filesize = filesize( $local_path );
            try { $content_hash = hash_file( 'sha256', $local_path ); } catch (Exception $e) { return false; }

            $dt = gmdate( 'Ymd\THis\Z' ); $ds = gmdate( 'Ymd' );

            $headers = [
                'host' => $host, 'x-amz-content-sha256' => $content_hash, 'x-amz-date' => $dt,
                'content-type' => 'application/octet-stream', 'content-length' => (string)$filesize, 'x-amz-acl' => 'private'
            ];
            ksort( $headers );

            $can_headers = ''; $signed_headers_arr = [];
            foreach ( $headers as $k => $v ) { $can_headers .= strtolower($k) . ':' . trim($v) . "\n"; $signed_headers_arr[] = strtolower($k); }
            $signed_headers = implode( ';', $signed_headers_arr );
            $canonical_request = "PUT\n{$uri}\n\n{$can_headers}\n{$signed_headers}\n{$content_hash}";
            
            // Signature
            $scope = "{$ds}/auto/s3/aws4_request";
            $string_to_sign = "AWS4-HMAC-SHA256\n{$dt}\n{$scope}\n" . hash( 'sha256', $canonical_request );
            $kSecret = 'AWS4' . $secret_key;
            $kDate = hash_hmac( 'sha256', $ds, $kSecret, true );
            $kRegion = hash_hmac( 'sha256', 'auto', $kDate, true );
            $kService = hash_hmac( 'sha256', 's3', $kRegion, true );
            $kSigning = hash_hmac( 'sha256', 'aws4_request', $kService, true );
            $signature = hash_hmac( 'sha256', $string_to_sign, $kSigning );
            $auth = "AWS4-HMAC-SHA256 Credential={$access_key}/{$scope}, SignedHeaders={$signed_headers}, Signature={$signature}";

            $curl_headers = []; foreach ( $headers as $k => $v ) $curl_headers[] = "$k: $v";
            $curl_headers[] = "Authorization: $auth"; $curl_headers[] = "Expect:";

            // Attempt
            $attempt = 0;
            while ( $attempt < 2 ) {
                $attempt++;
                $fp = fopen( $local_path, 'rb' );
                $ch = curl_init( $url );
                curl_setopt( $ch, CURLOPT_PUT, true ); curl_setopt( $ch, CURLOPT_INFILE, $fp );
                curl_setopt( $ch, CURLOPT_INFILESIZE, $filesize ); curl_setopt( $ch, CURLOPT_HTTPHEADER, $curl_headers );
                curl_setopt( $ch, CURLOPT_RETURNTRANSFER, true ); curl_setopt( $ch, CURLOPT_SSL_VERIFYPEER, false );
                $res = curl_exec( $ch ); $code = curl_getinfo( $ch, CURLINFO_HTTP_CODE );
                curl_close( $ch ); fclose( $fp );
                if ( $code >= 200 && $code < 300 ) return true;
                sleep( 1 );
            }
            return false;
        }

        // --- 2. COPY REMOTE (The "Rename" Logic) ---
        public static function copy_remote_file( $source_key, $dest_key ) {
            $account_id = AM_R2_ACCOUNT_ID;
            $bucket     = AM_R2_BUCKET;
            $access_key = AM_R2_ACCESS_KEY;
            $secret_key = AM_R2_SECRET_KEY;

            // Prepare Source/Dest
            $source_key = ltrim( str_replace( '\\', '/', $source_key ), '/' );
            $dest_key   = ltrim( str_replace( '\\', '/', $dest_key ), '/' );
            
            // Source must include bucket for x-amz-copy-source
            // NOTE: R2 requires URL encoding for the copy source
            $encoded_source = implode( '/', array_map( 'rawurlencode', explode( '/', $source_key ) ) );
            $copy_source = "/{$bucket}/{$encoded_source}";

            $encoded_dest = implode( '/', array_map( 'rawurlencode', explode( '/', $dest_key ) ) );
            $uri  = "/{$bucket}/{$encoded_dest}";
            $host = "{$account_id}.r2.cloudflarestorage.com";
            $url  = "https://{$host}{$uri}";

            $dt = gmdate( 'Ymd\THis\Z' ); $ds = gmdate( 'Ymd' );
            $content_hash = hash( 'sha256', '' ); // Empty payload for Copy

            $headers = [
                'host' => $host, 
                'x-amz-content-sha256' => $content_hash, 
                'x-amz-date' => $dt,
                'x-amz-copy-source' => $copy_source, // Critical Header
            ];
            ksort( $headers );

            $can_headers = ''; $signed_headers_arr = [];
            foreach ( $headers as $k => $v ) { $can_headers .= strtolower($k) . ':' . trim($v) . "\n"; $signed_headers_arr[] = strtolower($k); }
            $signed_headers = implode( ';', $signed_headers_arr );
            
            $canonical_request = "PUT\n{$uri}\n\n{$can_headers}\n{$signed_headers}\n{$content_hash}";
            
            $scope = "{$ds}/auto/s3/aws4_request";
            $string_to_sign = "AWS4-HMAC-SHA256\n{$dt}\n{$scope}\n" . hash( 'sha256', $canonical_request );
            $kSecret = 'AWS4' . $secret_key;
            $kDate = hash_hmac( 'sha256', $ds, $kSecret, true );
            $kRegion = hash_hmac( 'sha256', 'auto', $kDate, true );
            $kService = hash_hmac( 'sha256', 's3', $kRegion, true );
            $kSigning = hash_hmac( 'sha256', 'aws4_request', $kService, true );
            $signature = hash_hmac( 'sha256', $string_to_sign, $kSigning );
            $auth = "AWS4-HMAC-SHA256 Credential={$access_key}/{$scope}, SignedHeaders={$signed_headers}, Signature={$signature}";

            $curl_headers = []; foreach ( $headers as $k => $v ) $curl_headers[] = "$k: $v";
            $curl_headers[] = "Authorization: $auth";

            $ch = curl_init( $url );
            curl_setopt( $ch, CURLOPT_CUSTOMREQUEST, 'PUT' );
            curl_setopt( $ch, CURLOPT_HTTPHEADER, $curl_headers );
            curl_setopt( $ch, CURLOPT_RETURNTRANSFER, true );
            curl_setopt( $ch, CURLOPT_SSL_VERIFYPEER, false );
            $res = curl_exec( $ch ); $code = curl_getinfo( $ch, CURLINFO_HTTP_CODE );
            curl_close( $ch );

            return ( $code >= 200 && $code < 300 );
        }

        // --- 3. DELETE (Cleanup) ---
        public static function delete_file( $remote_key ) {
            $account_id = AM_R2_ACCOUNT_ID; $bucket = AM_R2_BUCKET;
            $access_key = AM_R2_ACCESS_KEY; $secret_key = AM_R2_SECRET_KEY;
            
            $remote_key = ltrim( str_replace( '\\', '/', $remote_key ), '/' );
            $encoded_key = implode( '/', array_map( 'rawurlencode', explode( '/', $remote_key ) ) );
            $uri = "/{$bucket}/{$encoded_key}";
            $host = "{$account_id}.r2.cloudflarestorage.com"; $url = "https://{$host}{$uri}";
            
            $dt = gmdate( 'Ymd\THis\Z' ); $ds = gmdate( 'Ymd' ); $content_hash = hash( 'sha256', '' );
            $headers = [ 'host' => $host, 'x-amz-content-sha256' => $content_hash, 'x-amz-date' => $dt ];
            ksort( $headers );
            
            $can = ''; $sig_h = []; foreach ( $headers as $k => $v ) { $can .= strtolower($k).':'.trim($v)."\n"; $sig_h[] = strtolower($k); }
            $sig_str = implode(';', $sig_h);
            $can_req = "DELETE\n{$uri}\n\n{$can}\n{$sig_str}\n{$content_hash}";
            
            $scope = "{$ds}/auto/s3/aws4_request";
            $sts = "AWS4-HMAC-SHA256\n{$dt}\n{$scope}\n" . hash('sha256', $can_req);
            $kSecret = 'AWS4'.$secret_key;
            $kDate = hash_hmac('sha256', $ds, $kSecret, true);
            $kRegion = hash_hmac('sha256', 'auto', $kDate, true);
            $kSvc = hash_hmac('sha256', 's3', $kRegion, true);
            $kSign = hash_hmac('sha256', 'aws4_request', $kSvc, true);
            $sig = hash_hmac('sha256', $sts, $kSign);
            $auth = "AWS4-HMAC-SHA256 Credential={$access_key}/{$scope}, SignedHeaders={$sig_str}, Signature={$sig}";
            
            $curl_headers = []; foreach ( $headers as $k => $v ) $curl_headers[] = "$k: $v";
            $curl_headers[] = "Authorization: $auth";

            $ch = curl_init( $url ); curl_setopt( $ch, CURLOPT_CUSTOMREQUEST, 'DELETE' );
            curl_setopt( $ch, CURLOPT_HTTPHEADER, $curl_headers ); curl_setopt( $ch, CURLOPT_RETURNTRANSFER, true );
            curl_setopt( $ch, CURLOPT_SSL_VERIFYPEER, false );
            $res = curl_exec( $ch ); $code = curl_getinfo( $ch, CURLINFO_HTTP_CODE ); curl_close( $ch );
            
            return ( $code >= 200 && $code < 300 );
        }
    }
}


/* ---------------------------------------------------------------------------
   PART 2: THE PROCESSOR (Now Cleans Old Thumbnails)
   --------------------------------------------------------------------------- */
if ( ! class_exists( 'Artmatter_Artwork_Processor' ) ) {

    class Artmatter_Artwork_Processor {

        public static function init() {
            add_action( 'save_post_product', [ self::class, 'process_product_artwork' ], 20, 3 );
            add_action( 'save_post_product', [ self::class, 'handle_artist_migration' ], 30, 3 );
            add_action( 'delete_attachment', [ self::class, 'delete_linked_attachment' ], 10, 1 );
        }

        public static function process_product_artwork( $post_id, $post, $update ) {
            if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return;
            if ( wp_is_post_revision( $post_id ) ) return;
            
            $attachment_id = get_post_thumbnail_id( $post_id );
            if ( ! $attachment_id ) return;
            
            // Unlock to allow renaming/fixing
            delete_post_meta( $attachment_id, '_artmatter_processed' );

            if ( ! get_attached_file( $attachment_id ) ) return;
            self::process_attachment( $attachment_id, $post );
        }

        public static function handle_artist_migration( $post_id, $post, $update ) { /* Migration Logic */ }

        private static function process_attachment( $attachment_id, $product ) {
            require_once( ABSPATH . 'wp-admin/includes/image.php' );
            require_once( ABSPATH . 'wp-admin/includes/file.php' );
            require_once( ABSPATH . 'wp-admin/includes/media.php' );

            $original_path = get_attached_file( $attachment_id );
            $upload_dir    = wp_get_upload_dir();
            $base_dir      = $upload_dir['basedir'];
            $product_title = $product->post_title;
            $artist_slug   = self::get_artwork_artist_slug( $product->ID ) ?: 'uncategorized';
            $path_parts    = pathinfo( $original_path );
            
            // --------------------------------------------------
            // 1. PUBLIC FILE (Cleanup + Rename)
            // --------------------------------------------------
            $safe_title = sanitize_title( $product_title );
            $new_name   = $safe_title . '-' . $product->ID; 
            
            $public_dir = path_join( $base_dir, "arts/artists/{$artist_slug}" );
            if ( ! file_exists( $public_dir ) ) wp_mkdir_p( $public_dir );

            $ext = $path_parts['extension'];
            $new_filename = $new_name . '.' . $ext;
            $public_path  = path_join( $public_dir, $new_filename );

            // Store the "Old Name" so we can find the Orphaned Master later
            $old_public_name_no_ext = $path_parts['filename'];

            if ( $original_path !== $public_path ) {
                self::cleanup_old_thumbnails( $attachment_id, $original_path );

                if ( @rename( $original_path, $public_path ) ) {
                     // Renamed
                } elseif ( @copy( $original_path, $public_path ) ) {
                    @unlink( $original_path ); 
                } else {
                    return; 
                }
                update_post_meta( $attachment_id, '_wp_attached_file', _wp_relative_upload_path( $public_path ) );
            }

            // --------------------------------------------------
            // 2. MASTER FILE (The "Rescue" Logic)
            // --------------------------------------------------
            $master_dir = path_join( $base_dir, "arts-master/artists/{$artist_slug}" );
            if ( ! file_exists( $master_dir ) ) wp_mkdir_p( $master_dir );
            
            $master_filename = $new_name . '-master.' . $ext;
            $master_path     = path_join( $master_dir, $master_filename );

            $master_id = get_post_meta( $attachment_id, '_artmatter_master_attachment_id', true );
            $new_r2_key = "arts-master/artists/{$artist_slug}/{$master_filename}";

            if ( $master_id && get_post( $master_id ) ) {
                // CASE A: Master IS linked in DB
                $registered_master_path = get_attached_file( $master_id );
                
                if ( $registered_master_path && file_exists( $registered_master_path ) ) {
                    // Local rename
                    if ( $registered_master_path !== $master_path ) {
                        if ( @rename( $registered_master_path, $master_path ) ) {
                            update_post_meta( $master_id, '_wp_attached_file', _wp_relative_upload_path( $master_path ) );
                            update_post_meta( $master_id, '_artmatter_r2_synced', false ); 
                        }
                    }
                } else {
                    // Cloud Rename
                    $old_r2_key = get_post_meta( $master_id, '_artmatter_r2_key', true );
                    if ( $old_r2_key && $old_r2_key !== $new_r2_key ) {
                         if ( class_exists( 'Artmatter_R2' ) ) {
                            if ( Artmatter_R2::copy_remote_file( $old_r2_key, $new_r2_key ) ) {
                                Artmatter_R2::delete_file( $old_r2_key ); // <--- This deletes the old R2 file
                                update_post_meta( $master_id, '_artmatter_r2_key', $new_r2_key );
                                update_post_meta( $master_id, '_wp_attached_file', _wp_relative_upload_path( $master_path ) );
                            }
                        }
                    }
                }
                wp_update_post([ 'ID' => $master_id, 'post_title' => $product_title . ' - Master' ]);

            } else {
                // CASE B: No Link Found (The Dangerous Part)
                
                // [CRITICAL FIX] "Legacy Discovery"
                // Check if a file exists with the OLD name + "-master"
                // e.g. "stoops-spoils" -> "stoops-spoils-master.jpg"
                $legacy_filename = $old_public_name_no_ext . '-master.' . $ext;
                $legacy_path     = path_join( $master_dir, $legacy_filename );

                // Also check specifically for "Filename + -master" in case it was already standard
                $legacy_path_alt = str_replace( '.' . $ext, '-master.' . $ext, $original_path ); 
                // Note: original_path is the OLD public path before we renamed it above.

                $source_to_use = '';
                
                if ( file_exists( $legacy_path ) ) {
                    // Found 13MB file using short name!
                    $source_to_use = $legacy_path;
                } elseif ( file_exists( $legacy_path_alt ) ) {
                    // Found 13MB file using full name!
                    $source_to_use = $legacy_path_alt;
                }

                if ( $source_to_use ) {
                    // WE FOUND THE ORIGINAL! Rename it to the new ID format.
                    @rename( $source_to_use, $master_path );
                } else {
                    // Only copy from public if we absolutely cannot find a master
                    @copy( $public_path, $master_path );
                }

                $master_data = [
                    'post_mime_type' => $ext === 'png' ? 'image/png' : 'image/jpeg',
                    'post_title'     => $product_title . ' - Master',
                    'post_status'    => 'inherit',
                ];
                $master_id = wp_insert_attachment( $master_data, $master_path );
                update_post_meta( $master_id, '_artmatter_is_master', true );
                update_post_meta( $master_id, '_artmatter_r2_synced', false );
            }

            // --------------------------------------------------
            // 3. R2 UPLOAD & CLEANUP
            // --------------------------------------------------
            if ( $master_id && ! is_wp_error( $master_id ) ) {
                $is_synced = get_post_meta( $master_id, '_artmatter_r2_synced', true );
                if ( ! $is_synced && file_exists( $master_path ) ) {
                    if ( class_exists( 'Artmatter_R2' ) ) {
                        // Upload
                        if ( Artmatter_R2::upload_file( $master_path, $new_r2_key ) ) {
                            update_post_meta( $master_id, '_artmatter_r2_key', $new_r2_key );
                            update_post_meta( $master_id, '_artmatter_r2_synced', true );
                            
                            // [ZERO STORAGE] Delete local file after successful upload
                            @unlink( $master_path ); 
                        }
                    }
                }
                update_post_meta( $master_id, '_wr2x_ignore', true );
                update_post_meta( $master_id, '_artmatter_processed', true );
                update_post_meta( $attachment_id, '_artmatter_master_attachment_id', $master_id );
                update_post_meta( $master_id, '_artmatter_public_attachment_id', $attachment_id );
            }

            // 4. GENERATE NEW THUMBNAILS
            $editor = wp_get_image_editor( $public_path );
            if ( ! is_wp_error( $editor ) ) {
                $editor->resize( 2000, 2000, false );
                $editor->save( $public_path );
            }
            
            wp_update_post([ 'ID' => $attachment_id, 'post_title' => $product_title ]);
            $alt = self::build_artwork_alt_text( $product_title, $product->ID );
            update_post_meta( $attachment_id, '_wp_attachment_image_alt', $alt );
            
            $public_meta = wp_generate_attachment_metadata( $attachment_id, $public_path );
            wp_update_attachment_metadata( $attachment_id, $public_meta );
            
            self::sync_rml_location( $attachment_id, $artist_slug );
        }

        private static function cleanup_old_thumbnails( $attachment_id, $original_path ) {
            $meta = wp_get_attachment_metadata( $attachment_id );
            if ( empty( $meta['sizes'] ) ) return;
            $dir = pathinfo( $original_path, PATHINFO_DIRNAME );
            foreach ( $meta['sizes'] as $size_info ) {
                if ( isset( $size_info['file'] ) ) {
                    $thumb_path = path_join( $dir, $size_info['file'] );
                    if ( file_exists( $thumb_path ) ) @unlink( $thumb_path );
                }
            }
        }
        
        // (Other helpers: get_artwork_artist_slug, build_artwork_alt_text, sync_rml_location, delete_linked_attachment -> Keep these as they were)
        private static function get_artwork_artist_slug( $post_id ) {
            $terms = get_the_terms( $post_id, 'artwork_artist' );
            if ( $terms && ! is_wp_error( $terms ) ) return $terms[0]->slug;
            $terms = get_the_terms( $post_id, 'artist' );
            if ( $terms && ! is_wp_error( $terms ) ) return $terms[0]->slug;
            $author_id = get_post_field( 'post_author', $post_id );
            $user = get_userdata( $author_id );
            return $user ? sanitize_title( $user->user_login ) : false;
        }

        private static function build_artwork_alt_text( $title, $id ) {
            $artist = get_post_meta( $id, 'artwork_artist_display_name', true );
            return $artist ? trim( $title ) . ' metal poster by ' . trim( $artist ) : trim( $title ) . ' metal poster';
        }
        
        private static function sync_rml_location( $attachment_id, $slug ) {
            if ( ! function_exists( 'wp_rml_create_or_return_existing_id' ) ) return;
            $root = _wp_rml_root();
            $f1 = wp_rml_create_or_return_existing_id( 'arts', $root, 0 );
            if ( is_wp_error( $f1 ) ) return;
            $f2 = wp_rml_create_or_return_existing_id( 'artists', $f1, 0 );
            if ( is_wp_error( $f2 ) ) return;
            $final = wp_rml_create_or_return_existing_id( $slug, $f2, 0 );
            if ( ! is_wp_error( $final ) ) wp_rml_move( $final, [ $attachment_id ] );
        }

        public static function delete_linked_attachment( $attachment_id ) {
            remove_action( 'delete_attachment', [ self::class, 'delete_linked_attachment' ], 10 );
            $master = get_post_meta( $attachment_id, '_artmatter_master_attachment_id', true );
            $public = get_post_meta( $attachment_id, '_artmatter_public_attachment_id', true );
            if ( $master ) wp_delete_attachment( $master, true );
            if ( $public ) wp_delete_attachment( $public, true );
            add_action( 'delete_attachment', [ self::class, 'delete_linked_attachment' ], 10, 1 );
        }
    }
    Artmatter_Artwork_Processor::init();
}

/**
 * Sync product_tag taxonomy <-> product_tags meta key
 * Works with Admin UI, REST API, and programmatic updates.
 */

class Product_Tag_Meta_Sync {

    /** Meta key used as proxy */
    private const META_KEY = 'product_tags';

    /** Target taxonomy */
    private const TAXONOMY = 'product_tag';

    /** Prevent infinite loops */
    private static bool $is_syncing = false;

    /**
     * Bootstrap hooks
     */
    public static function init(): void {

        // Meta → Taxonomy (when meta is updated directly)
        add_action( 'updated_post_meta', [ self::class, 'sync_meta_to_taxonomy' ], 10, 4 );
        add_action( 'added_post_meta',   [ self::class, 'sync_meta_to_taxonomy' ], 10, 4 );

        // Taxonomy → Meta (covers Admin + REST + wc/v3)
        add_action( 'set_object_terms',  [ self::class, 'sync_taxonomy_to_meta' ], 10, 6 );
    }

    /**
     * META → TAXONOMY
     * Triggered when product_tags meta is updated directly
     */
    public static function sync_meta_to_taxonomy(
        int $meta_id,
        int $object_id,
        string $meta_key,
        $meta_value
    ): void {

        if (
            self::$is_syncing ||
            $meta_key !== self::META_KEY ||
            get_post_type( $object_id ) !== 'product'
        ) {
            return;
        }

        self::$is_syncing = true;

        // Normalize meta value
        $meta_value = strtolower( (string) $meta_value );

        $tags = array_filter(
            array_map( 'trim', explode( ',', $meta_value ) )
        );

        if ( empty( $tags ) ) {
            self::$is_syncing = false;
            return;
        }

        // Assign taxonomy terms (replace existing)
        wp_set_post_terms( $object_id, $tags, self::TAXONOMY, false );

        // Ensure meta stays normalized
        $normalized = implode( ', ', $tags );
        $current    = get_post_meta( $object_id, self::META_KEY, true );

        if ( $current !== $normalized ) {
            update_post_meta( $object_id, self::META_KEY, $normalized );
        }

        self::$is_syncing = false;
    }

    /**
     * TAXONOMY → META
     * Triggered by Admin UI, REST API, wc/v3, wp_set_object_terms
     */
    public static function sync_taxonomy_to_meta(
        int $object_id,
        array $terms,
        array $tt_ids,
        string $taxonomy,
        bool $append,
        array $old_tt_ids
    ): void {

        if (
            self::$is_syncing ||
            $taxonomy !== self::TAXONOMY ||
            get_post_type( $object_id ) !== 'product'
        ) {
            return;
        }

        self::$is_syncing = true;

        // Fetch current term names
        $term_names = wp_get_post_terms(
            $object_id,
            self::TAXONOMY,
            [ 'fields' => 'names' ]
        );

        if ( is_wp_error( $term_names ) ) {
            self::$is_syncing = false;
            return;
        }

        // Normalize
        $term_names = array_unique(
            array_map( 'strtolower', $term_names )
        );

        $tags_string = implode( ', ', $term_names );
        $current     = get_post_meta( $object_id, self::META_KEY, true );

        // Only write if something actually changed
        if ( $tags_string !== $current ) {
            update_post_meta( $object_id, self::META_KEY, $tags_string );
        }

        self::$is_syncing = false;
    }
}

// Boot it
Product_Tag_Meta_Sync::init();

