/**
 * Real Media Library: Stable Physical Path Sync (Final)
 *
 * ✅ Correct timing (no more "empty folder" bug)
 * ✅ Works with:
 * - artist-profile/{nicename}
 * - custom-arts/{Y-m-d}
 * - arts/artists/{slug}
 * ✅ Includes fallback worker + resync helper
 */

// --------------------------------------------------
// DEBUG LOGGER
// --------------------------------------------------
if (!function_exists('rml_debug_log')) {
    function rml_debug_log($message) {
        $log_file = WP_CONTENT_DIR . '/rml_debug.log';
        $timestamp = date('Y-m-d H:i:s');
        $entry = '[' . $timestamp . '] ' . (is_array($message) || is_object($message) ? print_r($message, true) : $message) . "\n";
        file_put_contents($log_file, $entry, FILE_APPEND);
    }
}


// ==================================================
// PART 1: FINAL SYNC (MAIN LOGIC - RELIABLE)
// ==================================================
add_filter('wp_generate_attachment_metadata', 'rml_sync_after_metadata', 20, 2);

function rml_sync_after_metadata($metadata, $attachment_id) {

    // Prevent duplicate runs
    if ( get_post_meta($attachment_id, '_rml_synced_final', true) ) {
        return $metadata;
    }

    // Ensure RML functions exist
    if (
        !function_exists('wp_rml_create_or_return_existing_id') ||
        !function_exists('_wp_rml_root') ||
        !function_exists('wp_rml_move')
    ) {
        rml_debug_log("FINAL SYNC FAILED: RML functions missing for {$attachment_id}");
        return $metadata;
    }

    // Get relative path
    $relative = get_post_meta($attachment_id, '_wp_attached_file', true);

    if (empty($relative)) {
        rml_debug_log("FINAL SYNC FAILED: No relative path for {$attachment_id}");
        return $metadata;
    }

    $relative = wp_normalize_path($relative);
    $folder_path = dirname($relative);

    if ($folder_path === '.' || empty($folder_path)) {
        return $metadata;
    }

    $folder_path = trim($folder_path, '/\\');

    rml_debug_log("FINAL SYNC: {$attachment_id} → {$folder_path}");

    $folders = array_filter(explode('/', $folder_path), 'strlen');

    $parent = _wp_rml_root();
    $final_id = null;

    foreach ($folders as $folder) {
        $folder = trim($folder);
        if (!$folder) continue;

        $created = wp_rml_create_or_return_existing_id($folder, $parent, 0);

        if (is_wp_error($created)) {
            rml_debug_log("FINAL SYNC FAILED: " . $created->get_error_message());
            return $metadata;
        }

        $parent = $created;
        $final_id = $created;
    }

    if ($final_id) {
        $move = wp_rml_move($final_id, [$attachment_id]);

        if (is_wp_error($move)) {
            rml_debug_log("FINAL SYNC MOVE FAILED: " . $move->get_error_message());
        } else {
            rml_debug_log("FINAL SYNC SUCCESS: {$attachment_id} moved to {$folder_path}");
            update_post_meta($attachment_id, '_rml_synced_final', true);
        }
    }

    return $metadata;
}


// ==================================================
// PART 2: FALLBACK WORKER (SAFETY NET)
// ==================================================
add_action('add_attachment', 'rml_schedule_master_worker', 10, 1);

function rml_schedule_master_worker($attachment_id) {
    if ( get_post_meta($attachment_id, '_rml_master_worker_scheduled', true) ) {
        return;
    }

    wp_schedule_single_event(time() + 20, 'rml_async_master_worker', [$attachment_id]);
    update_post_meta($attachment_id, '_rml_master_worker_scheduled', true);

    rml_debug_log("SCHEDULED WORKER for {$attachment_id}");
}

add_action('rml_async_master_worker', 'rml_run_master_worker', 10, 1);

function rml_run_master_worker($attachment_id) {

    if ( get_post_meta($attachment_id, '_rml_synced_final', true) ) {
        return;
    }

    rml_debug_log("WORKER RUN: {$attachment_id}");

    require_once(ABSPATH . 'wp-admin/includes/image.php');

    $file = get_attached_file($attachment_id);

    if (!$file || !file_exists($file)) {
        rml_debug_log("WORKER FAILED: file missing");
        return;
    }

    // regenerate metadata (safe)
    $meta = wp_generate_attachment_metadata($attachment_id, $file);
    wp_update_attachment_metadata($attachment_id, $meta);
    
    // Note: The redundant call to rml_sync_after_metadata() has been removed from here.
}


// ==================================================
// PART 3: FORCE RESYNC (MANUAL FIX TOOL)
// ==================================================
function rml_force_resync_attachment($attachment_id) {

    delete_post_meta($attachment_id, '_rml_synced_final');
    delete_post_meta($attachment_id, '_rml_master_worker_scheduled');

    $meta = wp_get_attachment_metadata($attachment_id);

    rml_sync_after_metadata($meta, $attachment_id);

    if (!get_post_meta($attachment_id, '_rml_synced_final', true)) {
        wp_schedule_single_event(time() + 10, 'rml_async_master_worker', [$attachment_id]);
        update_post_meta($attachment_id, '_rml_master_worker_scheduled', true);
    }
}


// ==================================================
// PART 4: URL FIX (UNCHANGED)
// ==================================================
add_filter('wp_get_attachment_url', 'fix_custom_path_attachment_url', 99, 2);

function fix_custom_path_attachment_url($url, $attachment_id) {

    $file_path = get_post_meta($attachment_id, '_wp_attached_file', true);
    if (empty($file_path)) return $url;

    $custom_dirs = ['custom-arts', 'arts', 'artist-profile', 'arts-master', 'assets'];

    foreach ($custom_dirs as $dir) {
        if (strpos($file_path, $dir . '/') === 0) {
            $upload_dir = wp_get_upload_dir();
            return $upload_dir['baseurl'] . '/' . $file_path;
        }
    }

    return $url;
}

