/**
 * Plugin Name: Biteship Shipping for WooCommerce (Optimized + Editable Address v4.3.5)
 * Description: Biteship rates + automated address with an inline disclosure editor so customers can fix subdistrict/district while preserving city/province from API. This version is optimized for performance and stability with province alias normalization.
 * Version: 4.3.5
 * Author: Your Name
 */

if (!defined('ABSPATH')) {
    exit; // Exit if accessed directly.
}

/**
 * =================================================================
 * STEP 1: DEFINE THE SHIPPING METHOD CLASS
 * =================================================================
 */
if (class_exists('WC_Shipping_Method')) {
    class WC_Biteship_Shipping_Method extends WC_Shipping_Method {
        public $api_key;
        public $origin_zip;
        public $couriers;

        public function __construct($instance_id = 0) {
            parent::__construct($instance_id);
            $this->id                 = 'biteship_shipping';
            $this->instance_id        = absint($instance_id);
            $this->method_title       = __('Biteship Shipping', 'woocommerce');
            $this->method_description = __('Dynamically calculate shipping rates using the Biteship API.', 'woocommerce');
            $this->supports           = array('shipping-zones', 'instance-settings', 'instance-settings-modal');
            $this->init();
        }

        public function init() {
            $this->init_form_fields();
            $this->init_settings();
            $this->title      = $this->get_option('title', __('Biteship Shipping', 'woocommerce'));
            $this->enabled    = $this->get_option('enabled');
            $this->api_key    = $this->get_option('api_key');
            $this->origin_zip = $this->get_option('origin_zip');
            $this->couriers   = $this->get_option('couriers', 'jne,sicepat');
            add_action('woocommerce_update_options_shipping_' . $this->id, array($this, 'process_admin_options'));
        }

        public function init_form_fields() {
            $this->instance_form_fields = array(
                'title' => array('title' => __('Title', 'woocommerce'), 'type' => 'text', 'description' => __('This controls the title which the user sees during checkout.', 'woocommerce'), 'default' => __('Biteship Shipping', 'woocommerce'), 'desc_tip' => true),
                'api_key' => array('title' => __('Biteship API Key', 'woocommerce'), 'type' => 'text', 'description' => __('Enter your Biteship Live API Key.', 'woocommerce'), 'default' => ''),
                'origin_zip' => array('title' => __('Origin Postal Code', 'woocommerce'), 'type' => 'text', 'description' => __('The postal code of your warehouse or shipping origin.', 'woocommerce'), 'default' => '17142'),
                'couriers' => array('title' => __('Enabled Couriers', 'woocommerce'), 'type' => 'text', 'description' => __('Comma-separated list of courier codes (e.g., jne,sicepat,jnt).', 'woocommerce'), 'default' => 'jne,sicepat'),
            );
        }

        public function calculate_shipping($package = array()) {
            if ('no' === $this->enabled || empty($this->api_key)) return;
            if (!is_user_logged_in() && !WC()->customer->has_calculated_shipping() && !wp_doing_ajax()) return;
            if (!isset($package['destination']['country']) || 'ID' !== $package['destination']['country'] || empty($package['destination']['postcode'])) {
                WC()->session->__unset('biteship_destination_data');
                return;
            }
            if (!preg_match('/^\d{5}$/', $package['destination']['postcode'])) {
                WC()->session->__unset('biteship_destination_data');
                return;
            }

            $destination_zip = $package['destination']['postcode'];
            $stable_cart_items = [];
            foreach ($package['contents'] as $item_id => $values) {
                $stable_cart_items[$item_id] = ['product_id' => $values['product_id'], 'variation_id' => $values['variation_id'], 'quantity' => $values['quantity']];
            }
            $cart_hash     = md5(json_encode($stable_cart_items));
            $transient_key = 'biteship_rates_' . $destination_zip . '_' . $cart_hash;

            if (false !== ($cached_rates = get_transient($transient_key))) {
                if (false !== ($cached_session = get_transient($transient_key . '_session'))) {
                    WC()->session->set('biteship_destination_data', $cached_session);
                }
                foreach ($cached_rates as $rate_data) $this->add_rate($rate_data);
                return;
            }

            $items = [];
            foreach ($package['contents'] as $values) {
                $product     = $values['data'];
                $price       = (float) $product->get_price();
                $weight      = wc_get_weight($product->get_weight(), 'g');
                $item_weight = ($weight > 0) ? $weight : 1000;
                $items[]     = ['name' => $product->get_name(), 'value' => $price, 'weight' => $item_weight, 'quantity' => $values['quantity']];
            }

            $body = ['origin_postal_code' => (int)$this->origin_zip, 'destination_postal_code' => (int)$destination_zip, 'couriers' => $this->couriers, 'items' => $items];
            $response = wp_remote_post('https://api.biteship.com/v1/rates/couriers', ['headers' => ['Authorization' => $this->api_key, 'Content-Type' => 'application/json'], 'body' => json_encode($body), 'timeout' => 15]);

            if (is_wp_error($response)) {
                wc_get_logger()->error('Biteship API Error: ' . $response->get_error_message());
                return;
            }

            $response_body = json_decode(wp_remote_retrieve_body($response), true);
            if (isset($response_body['success']) && $response_body['success'] === true && !empty($response_body['pricing'])) {
                $destination_data = null;
                if (isset($response_body['destination'])) {
                    $d = $response_body['destination'];
                    $destination_data = [
                        'province'    => $d['administrative_division_level_1_name'],
                        'city'        => $d['administrative_division_level_2_name'],
                        'district'    => $d['administrative_division_level_3_name'],
                        'subdistrict' => $d['administrative_division_level_4_name'],
                    ];
                    WC()->session->set('biteship_destination_data', $destination_data);
                }
                $rates_to_cache = [];
                foreach ($response_body['pricing'] as $rate) {
                    if (isset($rate['shipping_type']) && $rate['shipping_type'] === 'parcel') {
                        $dr            = explode(' - ', $rate['shipment_duration_range']);
                        $duration_text = (count($dr) > 1 && $dr[0] != $dr[1]) ? $rate['shipment_duration_range'] . ' business days' : $dr[0] . ' business day';
                        $label         = sprintf('%s - %s', strtoupper($rate['courier_name']), strtoupper($rate['courier_service_code']));
                        $args = ['id' => $this->get_rate_id($rate['courier_code'] . '_' . $rate['courier_service_code']), 'label' => $label, 'cost' => $rate['price'], 'calc_tax' => 'per_order', 'meta_data' => ['_biteship_duration' => $duration_text]];
                        $this->add_rate($args);
                        $rates_to_cache[] = $args;
                    }
                }
                if (!empty($rates_to_cache)) {
                    set_transient($transient_key, $rates_to_cache, DAY_IN_SECONDS);
                    if ($destination_data) set_transient($transient_key . '_session', $destination_data, DAY_IN_SECONDS);
                }
            } else {
                WC()->session->__unset('biteship_destination_data');
                wc_get_logger()->error('Biteship API Response Error: ' . json_encode($response_body));
            }
        }
    }
}

