/**
 * Province label normalizer and alias mapping for ID provinces.
 * Maps variants like "Nanggroe Aceh Darussalam (NAD)" to "Daerah Istimewa Aceh" etc.
 */
function biteship_normalize_id_province_label( $label ) {
    $n = strtolower( trim( $label ?: '' ) );
    // remove bracketed suffixes e.g. "(NAD)"
    $n = preg_replace('/\s*\(.*?\)\s*/', '', $n);
    $n = preg_replace('/\s+/', ' ', $n);

    // Aliases for common mismatches vs WooCommerce canonical labels/codes.
    // WooCommerce canonical codes include AC (Daerah Istimewa Aceh), YO (Daerah Istimewa Yogyakarta), JK (DKI Jakarta).
    // Source for codes: WooCommerce state codes listing. [Reference in answer text]
    $aliases = array(
        // Aceh
        'nanggroe aceh darussalam' => 'Daerah Istimewa Aceh',
        'nad'                      => 'Daerah Istimewa Aceh',
        'aceh'                     => 'Daerah Istimewa Aceh',
        // Yogyakarta
        'di yogyakarta'            => 'Daerah Istimewa Yogyakarta',
        'diy'                      => 'Daerah Istimewa Yogyakarta',
        'yogyakarta'               => 'Daerah Istimewa Yogyakarta',
        // Jakarta
        'jakarta'                  => 'DKI Jakarta',
        'dki'                      => 'DKI Jakarta',
        'dki jakarta'              => 'DKI Jakarta',
    );

    if ( isset( $aliases[ $n ] ) ) {
        return $aliases[ $n ];
    }

    // Title-case fallback
    return ucwords( $n );
}

/**
 * Resolve WooCommerce state code from province label with alias normalization.
 */
function biteship_get_province_code_from_name($province_name, $country_code) {
    if (empty($province_name) || empty($country_code)) return '';
    $states = WC()->countries->get_states($country_code);
    if (empty($states)) return '';

    // 1) Try canonical alias first
    $canonical = biteship_normalize_id_province_label($province_name);
    foreach ($states as $code => $name) {
        if (strcasecmp(trim($name), trim($canonical)) === 0) return $code;
    }

    // 2) Normalized comparison safety net
    $norm = function($s) {
        $s = strtolower(trim($s));
        $s = preg_replace('/\s*\(.*?\)\s*/', '', $s);
        $s = preg_replace('/[^a-z0-9]+/', ' ', $s);
        return trim($s);
    };
    $needle = $norm($canonical);
    foreach ($states as $code => $name) {
        if ($norm($name) === $needle) return $code;
    }

    // 3) Optional: log for observability
    if (function_exists('wc_get_logger')) {
        wc_get_logger()->warning('Biteship province unmapped: ' . $province_name . ' (canonical: ' . $canonical . ')');
    }
    return '';
}

function biteship_modify_posted_address_data($data) {
    if (!is_checkout() || !WC()->session) return $data;

    $session_data = WC()->session->get('biteship_destination_data');
    $sub_override  = isset($_POST['biteship_subdistrict_override']) ? wc_clean(wp_unslash($_POST['biteship_subdistrict_override'])) : null;
    $dist_override = isset($_POST['biteship_district_override']) ? wc_clean(wp_unslash($_POST['biteship_district_override'])) : null;

    if ($session_data && ($sub_override !== null || $dist_override !== null)) {
        if ($sub_override !== null) $session_data['subdistrict'] = $sub_override;
        if ($dist_override !== null) $session_data['district'] = $dist_override;
        WC()->session->set('biteship_destination_data', $session_data);
    }

    $biteship_data = WC()->session->get('biteship_destination_data');

    if (!$biteship_data || !isset($data['billing_country']) || 'ID' !== $data['billing_country']) {
        return $data;
    }

    if (!empty($biteship_data['city'])) $data['billing_city'] = $biteship_data['city'];
    if (!empty($biteship_data['province'])) {
        $state_code = biteship_get_province_code_from_name($biteship_data['province'], $data['billing_country']);
        if ($state_code) $data['billing_state'] = $state_code;
    }

    if (!empty($data['ship_to_different_address'])) {
        if (!empty($biteship_data['city'])) $data['shipping_city'] = $biteship_data['city'];
        if (!empty($biteship_data['province'])) {
            $state_code = biteship_get_province_code_from_name($biteship_data['province'], $data['shipping_country']);
            if ($state_code) $data['shipping_state'] = $state_code;
        }
    }

    $area_details = array_filter([
        $biteship_data['subdistrict'] ?? null,
        $biteship_data['district'] ?? null
    ]);

    if (!empty($area_details)) {
        $area_details_string = implode(', ', $area_details);
        $data['billing_address_2'] = $area_details_string;

        if (!empty($data['ship_to_different_address'])) {
            $data['shipping_address_2'] = $area_details_string;
        }
    }

    return $data;
}
add_filter('woocommerce_checkout_posted_data', 'biteship_modify_posted_address_data');

function biteship_save_address_to_order_meta($order_id) {
    if (!$order_id || !WC()->session || !WC()->session->get('biteship_destination_data')) return;
    $order = wc_get_order($order_id);
    if (!$order) return;
    $data = WC()->session->get('biteship_destination_data');
    $fields_to_save = ['district', 'subdistrict'];
    foreach ($fields_to_save as $field) {
        if (!empty($data[$field])) {
            $order->update_meta_data('_billing_' . $field, $data[$field]);
            if ($order->get_shipping_address_1()) $order->update_meta_data('_shipping_' . $field, $data[$field]);
        }
    }
    $order->save();
}
add_action('woocommerce_checkout_update_order_meta', 'biteship_save_address_to_order_meta');

