/**
 * =================================================================
 * STEP 4: INLINE JS/CSS — REFACTORED FOR PERFORMANCE + PROVINCE NORMALIZATION
 * =================================================================
 */
function biteship_inline_checkout_scripts() {
    if (!function_exists('is_checkout') || !is_checkout() || is_wc_endpoint_url()) {
        return;
    }
    $javascript = <<<'JS'
<script id="biteship-checkoutwc-integration-optimized">
jQuery(function ($) {
    const $body = $(document.body);
    if ($body.data('biteship-initialized')) return;

    // --- Cache selectors ---
    const $head = $('head');
    const $checkoutForm = $('form.checkout');
    const $billingCountry = $('#billing_country');
    const $billingAddress2 = $('#billing_address_2');
    const $shippingAddress2 = $('#shipping_address_2');
    // rows for Address 2 visibility
    const $billingAddress2FieldRow = $('#billing_address_2_field').closest('.row');
    const $shippingAddress2FieldRow = $('#shipping_address_2_field').closest('.row');
    const $addressHeader = $('#cfw-customer-info-address > h3');
    const $firstNameField = $('#billing_first_name_field');
    const $lastNameField = $('#billing_last_name_field');
    const $address1Field = $('#billing_address_1_field');
    const $countryField = $('#billing_country_field');
    const $postcodeFieldWrapper = $('#billing_postcode_field');
    const $cityField = $('#billing_city_field');
    const $stateField = $('#billing_state_field');

    // --- Province synonyms and helpers (alias-aware selection) ---
    const ID_PROVINCE_SYNONYMS = {
      'nanggroe aceh darussalam': 'Daerah Istimewa Aceh',
      'nad': 'Daerah Istimewa Aceh',
      'aceh': 'Daerah Istimewa Aceh',
      'di yogyakarta': 'Daerah Istimewa Yogyakarta',
      'diy': 'Daerah Istimewa Yogyakarta',
      'yogyakarta': 'Daerah Istimewa Yogyakarta',
      'jakarta': 'DKI Jakarta',
      'dki': 'DKI Jakarta',
      'dki jakarta': 'DKI Jakarta'
    };
    function normProv(s){
      return (s || '').toLowerCase().replace(/\s*\(.*?\)\s*/g,'').replace(/[^a-z0-9]+/g,' ').trim();
    }
    function canonicalProv(label){
      const n = normProv(label);
      return ID_PROVINCE_SYNONYMS[n] || label;
    }
    function setProvinceSelectFromLabel($select, label){
      const target = canonicalProv(label);
      const needle = normProv(target);
      const $opts = $select.find('option');
      let $hit = $opts.filter((i, el) => normProv($(el).text()) === needle);
      if ($hit.length) {
        // ensure writable before setting
        $select.prop('readonly', false).val($hit.val()).trigger('change');
        // clear parsley/UI errors if any
        $select.removeClass('parsley-error')
               .closest('.cfw-input-wrap')
               .find('.parsley-errors-list').empty();
        return true;
      }
      return false;
    }

    // --- State Variables ---
    let debounceTimer;
    let isBiteshipAddressValid = false;
    let currentPostcode = '';
    let isAwaitingBiteshipResponse = false;
    let userAddressCache = null;
    let previousCountry = $billingCountry.val();

    function setupDOM() {
        const style = `<style>
        .biteship-automated-address-field input[readonly]{background-color:#f0f0f0!important;cursor:default!important}
        .biteship-error-message input{color:#d9534f!important;border-color:#d9534f!important}
        .cfw-button-disabled{opacity:.65;cursor:not-allowed!important;pointer-events:none}
        .biteship-hidden-field{display:none!important}
        .bte-edit-wrap{margin-top:-7px;margin-bottom:10px}
        .bte-toggle-link{background:none;border:0;padding:0;margin:0;color:var(--gray-1);font-size:.75em;text-decoration:underline;cursor:pointer}
        .bte-toggle-link:hover{color:var(--trp-lt-300)}
        .biteship-token-editor{display:none;gap:6px;flex-wrap:wrap;margin-top:6px;margin-bottom:15px}
        .biteship-token-editor.active{display:flex}
        .bte-token{padding:10px 12px 5px;border:1px solid #ddd;border-radius:6px;background:#fff;min-width:40px;color:var(--dark-1)}
        .bte-token[contenteditable="true"]:focus{outline:0;box-shadow:0 0 0 1px var(--cfw-buttons-primary-background-color)!important}
        </style>`;
        $head.append(style);

        $checkoutForm.append('<input type="hidden" id="biteship_subdistrict_override" name="biteship_subdistrict_override">');
        $checkoutForm.append('<input type="hidden" id="biteship_district_override" name="biteship_district_override">');

        const automatedFieldId = 'biteship_automated_input_billing';
        const newFieldHTML = `
            <div class="row cfw-input-wrap-row biteship-automated-address-field biteship-hidden-field">
                <p class="form-row col-lg-12 cfw-text-input cfw-input-wrap">
                    <label for="${automatedFieldId}" class="cfw-floatable-label">Automated Address</label>
                    <span class="woocommerce-input-wrapper"><input type="text" class="input-text" id="${automatedFieldId}" readonly  placeholder="Enter postcode for automated address"></span>
                </p>
            </div>
            <div id="bte-edit-toggle" class="bte-edit-wrap" style="display: none;">
                <button type="button" class="bte-toggle-link" aria-expanded="false" aria-controls="biteship_token_editor">Incorrect address? Edit</button>
            </div>
            <div id="biteship_token_editor" class="biteship-token-editor" role="group" aria-hidden="true">
                <span class="bte-token" data-key="subdistrict" contenteditable="true"></span>
                <span class="bte-token" data-key="district" contenteditable="true"></span>
            </div>`;
        $postcodeFieldWrapper.closest('.row').after(newFieldHTML);
    }

    function populateTokenEditor(address) {
        const $editor = $('#biteship_token_editor');
        const $toggle = $('#bte-edit-toggle');

        const setToken = (key, val) => {
            const $el = $editor.find(`.bte-token[data-key="${key}"]`);
            $el.text(val || '').attr('data-orig', val || '');
        };

        if (address) {
            setToken('subdistrict', address.subdistrict);
            setToken('district', address.district);
            $editor.data({ 'city': address.city || '', 'province': address.province || '' });
            $toggle.show();
        } else {
            setToken('subdistrict', '');
            setToken('district', '');
            $editor.data({ 'city': '', 'province': '' });
            $('#biteship_subdistrict_override, #biteship_district_override').val('');
            $toggle.hide();
            $editor.removeClass('active').attr('aria-hidden', 'true');
            $toggle.find('button').attr('aria-expanded', 'false').text('Incorrect address? Edit');
        }
    }

    function toggleContinueButtonState() {
        $('.cfw-continue-to-shipping-btn, .cfw-continue-to-payment-btn, .cfw-shipping-method a, .cfw-payment-method a')
            .toggleClass('cfw-button-disabled', !isBiteshipAddressValid);
    }

    function updateAddressFieldsVisibility() {
        const selectedMethod = $('input[name="cfw_delivery_method"]:checked').val();
        const selectedCountry = $billingCountry.val();
        const $automatedField = $('.biteship-automated-address-field');

        if (selectedMethod === 'pickup') {
            $addressHeader.text('Contact Information');
            if (userAddressCache === null) {
                userAddressCache = { address1: $('#billing_address_1').val(), city: $('#billing_city').val(), postcode: $('#billing_postcode').val(), state: $('#billing_state').val() };
            }
            $address1Field.add($countryField).add($postcodeFieldWrapper).add($cityField).add($stateField).add($automatedField).add($billingAddress2FieldRow).addClass('biteship-hidden-field');
            $('#bte-edit-toggle, #biteship_token_editor').hide();
            $firstNameField.add($lastNameField).removeClass('col-lg-12').addClass('col-lg-6');
            $('#billing_address_1').val('Store Pickup'); $('#billing_city').val('Store Pickup'); $('#billing_postcode').val('10000'); $('#billing_state').val('JK');
            isBiteshipAddressValid = true;
        } else {
            $addressHeader.text('Billing and Shipping address');
            if (userAddressCache !== null) {
                $('#billing_address_1').val(userAddressCache.address1);
                $('#billing_city').val(userAddressCache.city);
                $('#billing_postcode').val(userAddressCache.postcode);
                $('#billing_state').val(userAddressCache.state);
                currentPostcode = userAddressCache.postcode;
                userAddressCache = null;
                if (currentPostcode && currentPostcode.match(/^\d{5}$/)) {
                    isAwaitingBiteshipResponse = true;
                    $postcodeFieldWrapper.addClass('cfw-loading');
                    $body.trigger('update_checkout');
                }
            }
            $address1Field.add($countryField).add($postcodeFieldWrapper).removeClass('biteship-hidden-field');
            $firstNameField.add($lastNameField).removeClass('col-lg-12').addClass('col-lg-6');

            if (selectedCountry === 'ID') {
                $cityField.add($stateField).addClass('biteship-hidden-field');
                $billingAddress2FieldRow.addClass('biteship-hidden-field');
                $shippingAddress2FieldRow.addClass('biteship-hidden-field');

                $automatedField.removeClass('biteship-hidden-field');
                $countryField.add($postcodeFieldWrapper).addClass('col-lg-6');
                const postcode = $('#billing_postcode').val();
                const automatedAddress = $('#biteship_automated_input_billing').val();
                isBiteshipAddressValid = postcode && postcode.match(/^\d{5}$/) && automatedAddress && automatedAddress.indexOf('not found') === -1;
                if (isBiteshipAddressValid) $('#bte-edit-toggle').show();
            } else { // Non-ID countries
                $cityField.add($stateField).removeClass('biteship-hidden-field');
                $billingAddress2FieldRow.removeClass('biteship-hidden-field');
                $shippingAddress2FieldRow.removeClass('biteship-hidden-field');

                $automatedField.addClass('biteship-hidden-field');
                $('#bte-edit-toggle, #biteship_token_editor').hide();
                $countryField.add($postcodeFieldWrapper).removeClass('col-lg-6');
                isBiteshipAddressValid = true;
            }
        }
        toggleContinueButtonState();
    }

    function bindEvents() {
        $('#billing_postcode').on('keyup', function () {
            if ($billingCountry.val() !== 'ID') return;
            const postcode = $(this).val();
            if (postcode === currentPostcode) return;
            currentPostcode = postcode;

            clearTimeout(debounceTimer);
            const $automatedInput = $('#biteship_automated_input_billing');
            $automatedInput.val('').closest('p').removeClass('biteship-error-message');
            isBiteshipAddressValid = false;

            if (postcode && postcode.match(/^\d{5}$/)) {
                $postcodeFieldWrapper.addClass('cfw-loading');
                $(this).prop('readonly', true);
                $automatedInput.val('Looking up address...').closest('p').addClass('cfw-label-is-floated');
                debounceTimer = setTimeout(() => {
                    isAwaitingBiteshipResponse = true;
                    $body.trigger('update_checkout');
                }, 500);
            } else {
                populateTokenEditor(null);
                toggleContinueButtonState();
                if (postcode === '') $body.trigger('update_checkout');
            }
        });

        $(document).on('click', '.bte-toggle-link', function() {
            const $editor = $('#biteship_token_editor');
            const isOpen = $editor.toggleClass('active').hasClass('active');
            $(this).attr('aria-expanded', isOpen).text(isOpen ? 'Done' : 'Incorrect address? Edit');
            $editor.attr('aria-hidden', !isOpen);
            if(isOpen) $editor.find('.bte-token:first').focus();
        });

        $('#biteship_token_editor').on('input blur keydown', '.bte-token', function(e) {
            if (e.type === 'keydown' && (e.key === ',' || e.key === 'Enter')) e.preventDefault();
            const sanitize = s => (s || '').replace(/[\r\n,]+/g, ' ').trim();
            const $editor = $('#biteship_token_editor');
            const sub = sanitize($editor.find('.bte-token[data-key="subdistrict"]').text());
            const dist = sanitize($editor.find('.bte-token[data-key="district"]').text());
            const city = $editor.data('city') || '';
            const prov = $editor.data('province') || '';

            $('#biteship_subdistrict_override').val(sub);
            $('#biteship_district_override').val(dist);

            const fallbackSub = $editor.find('.bte-token[data-key="subdistrict"]').attr('data-orig');
            const fallbackDist = $editor.find('.bte-token[data-key="district"]').attr('data-orig');

            const full = [sub || fallbackSub, dist || fallbackDist, city, prov].filter(Boolean).join(', ');
            $('#biteship_automated_input_billing').val(full);

            const areaDetails = [sub || fallbackSub, dist || fallbackDist].filter(Boolean).join(', ');
            $billingAddress2.val(areaDetails);
            if ($('#ship-to-different-address-checkbox').is(':checked')) {
                $shippingAddress2.val(areaDetails);
            }
        });

        $body.on('change', 'input[name="cfw_delivery_method"], #ship-to-different-address-checkbox', updateAddressFieldsVisibility);
        $billingCountry.on('change', function() {
            const newCountry = $(this).val();
            updateAddressFieldsVisibility();
            if ((newCountry === 'ID' && previousCountry !== 'ID') || (newCountry !== 'ID' && previousCountry === 'ID')) {
                $body.trigger('update_checkout');
            }
            previousCountry = newCountry;
        });

        $body.on('updated_checkout', function (event, data) {
            const $postcodeField = $('#billing_postcode');
            $postcodeField.prop('readonly', false);
            $postcodeFieldWrapper.removeClass('cfw-loading');

            if ($billingCountry.val() !== 'ID' || !isAwaitingBiteshipResponse) {
                if ($billingCountry.val() !== 'ID') updateAddressFieldsVisibility();
                return;
            }
            isAwaitingBiteshipResponse = false;

            const $automatedInput = $('#biteship_automated_input_billing');
            const $automatedInputWrapper = $automatedInput.closest('p');

            if (data && data.fragments && data.fragments.biteship_destination_data) {
                const address = data.fragments.biteship_destination_data;
                isBiteshipAddressValid = true;

                // City
                $('#billing_city').val(address.city);

                // Province select (alias-aware match)
                setProvinceSelectFromLabel($('#billing_state'), address.province);
                if ($('#ship-to-different-address-checkbox').is(':checked')) {
                    setProvinceSelectFromLabel($('#shipping_state'), address.province);
                }

                // Automated readout
                const fullAddress = [address.subdistrict, address.district, address.city, address.province].filter(Boolean).join(', ');
                $automatedInput.val(fullAddress);
                $automatedInputWrapper.removeClass('biteship-error-message').addClass('cfw-label-is-floated');
                populateTokenEditor(address);

                // Address 2 mirrors subdistrict/district
                const areaDetails = [address.subdistrict, address.district].filter(Boolean).join(', ');
                $billingAddress2.val(areaDetails);
                if ($('#ship-to-different-address-checkbox').is(':checked')) {
                    $shippingAddress2.val(areaDetails);
                }

            } else {
                isBiteshipAddressValid = false;
                if ($postcodeField.val().match(/^\d{5}$/)) {
                    $automatedInput.val('Postal code not found. Please check.');
                    $automatedInputWrapper.addClass('biteship-error-message').addClass('cfw-label-is-floated');
                } else {
                    $automatedInput.val('');
                    $automatedInputWrapper.removeClass('biteship-error-message cfw-label-is-floated');
                }
                populateTokenEditor(null);

                $billingAddress2.val('');
                if ($('#ship-to-different-address-checkbox').is(':checked')) {
                    $shippingAddress2.val('');
                }
            }
            toggleContinueButtonState();
        });
    }

    function init() {
        if (!$postcodeFieldWrapper.length) return;
        setupDOM();
        bindEvents();
        updateAddressFieldsVisibility();
        $body.data('biteship-initialized', true);

        const $postcodeField = $('#billing_postcode');
        if ($('input[name="cfw_delivery_method"]:checked').val() !== 'pickup' && $billingCountry.val() === 'ID' && $postcodeField.val().match(/^\d{5}$/)) {
            isAwaitingBiteshipResponse = true;
            $body.trigger('update_checkout');
        }
    }

    init();
});
</script>
JS;
    echo $javascript;
}
add_action('wp_footer', 'biteship_inline_checkout_scripts', 99);

/**
 * ============================================================
 * Product ↔ Artist Collection Sync (Complete & Resilient)
 *
 * Source of truth:
 * - Taxonomy: artist_collection
 * - ACF field: artwork_artist_collection (taxonomy field)
 *
 * Guarantees:
 * - REST API updates (n8n)
 * - Manual wp-admin edits
 * - Admin saves without field changes
 * - Advanced Bulk Edit / price updates
 * - Programmatic & plugin-based saves
 *
 * Writes denormalized product meta:
 * - artwork_artist_collection_name
 * - artwork_artist_collection_slug
 *
 * Company: Artmatter
 * ============================================================
 */


/**
 * ============================================================
 * Shared Resolver
 *
 * Writes artist_collection name + slug
 * to product post meta.
 * ============================================================
 */
function artmatter_write_artwork_artist_collection_meta( $post_id, $term_id ) {

    if ( ! $post_id || ! $term_id ) {
        return;
    }

    $term = get_term( (int) $term_id, 'artist_collection' );

    if ( ! $term || is_wp_error( $term ) ) {
        return;
    }

    update_post_meta( $post_id, 'artwork_artist_collection_name', $term->name );
    update_post_meta( $post_id, 'artwork_artist_collection_slug', $term->slug );
}


/**
 * ============================================================
 * ACF Taxonomy Field Update Hook (PRIMARY)
 *
 * Fires ONLY when the ACF taxonomy field value changes.
 * Works for:
 * - REST API (n8n PUT)
 * - Manual admin edits
 *
 * This is the most precise and preferred trigger.
 * ============================================================
 */
add_filter(
    'acf/update_value/name=artwork_artist_collection',
    'artmatter_sync_from_acf_field_update',
    10,
    3
);

function artmatter_sync_from_acf_field_update( $value, $post_id, $field ) {

    // Only products
    if ( get_post_type( $post_id ) !== 'product' ) {
        return $value;
    }

    // Empty value → cleanup
    if ( empty( $value ) ) {
        delete_post_meta( $post_id, 'artwork_artist_collection_name' );
        delete_post_meta( $post_id, 'artwork_artist_collection_slug' );
        return $value;
    }

    // Normalize (taxonomy fields may return array)
    if ( is_array( $value ) ) {
        $value = reset( $value );
    }

    $term_id = (int) $value;

    if ( $term_id ) {
        artmatter_write_artwork_artist_collection_meta( $post_id, $term_id );
    }

    // IMPORTANT: always return original value
    return $value;
}


/**
 * ============================================================
 * ACF Save Hook (ADMIN FALLBACK)
 *
 * Fires on EVERY wp-admin save,
 * even when the ACF field value did NOT change.
 *
 * Covers:
 * - Manual “Update” clicks
 * - Editorial saves with no taxonomy change
 * ============================================================
 */
add_action( 'acf/save_post', 'artmatter_sync_on_acf_save', 30 );

function artmatter_sync_on_acf_save( $post_id ) {

    // acf/save_post can receive non-post IDs
    if ( ! is_numeric( $post_id ) ) {
        return;
    }

    $post_id = (int) $post_id;

    if ( get_post_type( $post_id ) !== 'product' ) {
        return;
    }

    $term_id = get_field( 'artwork_artist_collection', $post_id );

    if ( empty( $term_id ) ) {
        return;
    }

    if ( is_array( $term_id ) ) {
        $term_id = reset( $term_id );
    }

    artmatter_write_artwork_artist_collection_meta( $post_id, (int) $term_id );
}


/**
 * ============================================================
 * Core Taxonomy Fallback (CRITICAL)
 *
 * Fires when:
 * - Advanced Bulk Edit updates price/stock
