/**
 * Artmatter — Deterministic Product Slug: {post_title}-{post_id}
 * Excludes products in Misc & Accessories categories
 */

if ( ! defined( 'ABSPATH' ) ) {
    exit;
}

add_filter(
    'wp_unique_post_slug',
    'artmatter_force_product_slug_with_id',
    10,
    6
);

function artmatter_force_product_slug_with_id(
    $slug,
    $post_id,
    $post_status,
    $post_type,
    $post_parent,
    $original_slug
) {
    // Only WooCommerce products
    if ( $post_type !== 'product' ) {
        return $slug;
    }

    // Skip autosaves, revisions, or if the post doesn't have a real ID yet
    if ( empty( $post_id ) || wp_is_post_autosave( $post_id ) || wp_is_post_revision( $post_id ) ) {
        return $slug;
    }

    // Skip custom products by meta
    if ( get_post_meta( $post_id, '_artmatter_custom_product', true ) === '1' ) {
        return $slug;
    }

    // (The REST_REQUEST check was removed here to allow WooCommerce interface saves to work)

    /**
     * EXCLUDED CATEGORIES (by slug)
     */
    $excluded_category_slugs = [
        'misc',
        'accessories',
    ];

    $product_terms = wp_get_post_terms(
        $post_id,
        'product_cat',
        [ 'fields' => 'slugs' ]
    );

    if ( ! is_wp_error( $product_terms ) && array_intersect( $excluded_category_slugs, $product_terms ) ) {
        // Let WordPress handle slug normally (no -{post_id})
        return $slug;
    }

    /**
     * Build deterministic slug
     */
    // Use the proposed $slug (which contains the new title), NOT get_the_title()
    $base_slug = empty( $slug ) ? 'product' : $slug;
    
    $id_suffix = '-' . $post_id;

    // Check if the slug already ends with the post ID to prevent duplicates (e.g., product-123-123)
    if ( substr( $base_slug, -strlen( $id_suffix ) ) === $id_suffix ) {
        return $base_slug;
    }

    return $base_slug . $id_suffix;
}

add_filter( 'rest_authentication_errors', 'lock_down_users_api', 10, 1 );

function lock_down_users_api( $result ) {
    // 1. If an error is already present (e.g., bad nonce), return it.
    if ( ! empty( $result ) ) {
        return $result;
    }

    // 2. Get the current requested route
    // Note: This covers both the user list (/users) and single users (/users/17)
    $route = $GLOBALS['wp']->query_vars['rest_route'] ?? '';

    // 3. Check if the request is targeting the Users endpoint
    if ( strpos( $route, '/wp/v2/users' ) !== false ) {
        
        // 4. If the user is NOT logged in, block them.
        if ( ! is_user_logged_in() ) {
            return new WP_Error( 
                'rest_forbidden', 
                'You must be authorized to view user data.', 
                array( 'status' => 401 ) 
            );
        }
    }

    return $result;
}

// Display parent artist-collection terms as "Singles" on the frontend.
add_filter( 'get_term', function ( $term, $taxonomy ) {

	// Safety checks
	if ( ! $term || is_wp_error( $term ) ) {
		return $term;
	}

	if ( ! $term instanceof WP_Term ) {
		return $term;
	}

	// Only affect artist_collection taxonomy
	if ( $taxonomy !== 'artist_collection' ) {
		return $term;
	}

	// Only modify parent terms
	if ( (int) $term->parent !== 0 ) {
		return $term;
	}

	// IMPORTANT: clone the term to avoid global side-effects
	$term = clone $term;
	$term->name = 'Singles';

	return $term;

}, 10, 2 );

