/**
 * Main generator
 */
function auto_set_aelia_currency_prices( $post_id ) {

    if ( defined('DOING_AUTOSAVE') && DOING_AUTOSAVE ) return;
    if ( wp_is_post_revision( $post_id ) ) return;

    $product = wc_get_product( $post_id );
    if ( ! $product ) return;

    $base_regular = get_post_meta( $post_id, '_regular_price', true );
	$base_sale    = get_post_meta( $post_id, '_sale_price', true );

	if ( ! is_numeric( $base_regular ) || $base_regular <= 0 ) {
		return;
	}


    if ( ! is_numeric( $base_regular ) || $base_regular <= 0 ) {
        return;
    }

    // Exchange rates (1 IDR → foreign)
    $rates = [
        'USD' => 0.000059,
        'EUR' => 0.000051,
        'AUD' => 0.000089,
        'JPY' => 0.00935,
        'SGD' => 0.000076,
        'CAD' => 0.000082,
        'CHF' => 0.000047,
        'GBP' => 0.000044,
        'HKD' => 0.000462,
        'THB' => 0.001866,
        'KRW' => 0.086400,
    ];

    $markup = 1.15;

    $regular_prices_arr = [];
    $sale_prices_arr    = [];

    // Price calculation rules
    $calculate_price = function( $amount, $rate, $markup, $currency ) {
        $raw = $amount * $rate * $markup;

        // THB → like 1990
        if ( $currency === 'THB' ) {
            $rounded = ( ceil( $raw / 100 ) * 100 ) - 10;
            return number_format( $rounded, 0, '.', '' );
        }

        // KRW → nearest 500
        if ( $currency === 'KRW' ) {
            $rounded = ceil( $raw / 500 ) * 500;
            return number_format( $rounded, 0, '.', '' );
        }

        // HKD → ends in 9
        if ( $currency === 'HKD' ) {
            $rounded = ( ceil( $raw / 10 ) * 10 ) - 1;
            return number_format( $rounded, 0, '.', '' );
        }

        // JPY → nearest 50
        if ( $currency === 'JPY' ) {
            $rounded = ceil( $raw / 50 ) * 50;
            return number_format( $rounded, 0, '.', '' );
        }

        // Default → .90 ending
        $rounded = ceil( $raw / 10 ) * 10 - 1;
		return number_format( $rounded, 0, '.', '' );
    };

    foreach ( $rates as $currency => $rate ) {
        $regular_prices_arr[ $currency ] = $calculate_price(
            $base_regular,
            $rate,
            $markup,
            $currency
        );

        if ( is_numeric( $base_sale ) && $base_sale > 0 ) {
            $sale_prices_arr[ $currency ] = $calculate_price(
                $base_sale,
                $rate,
                $markup,
                $currency
            );
        }
    }

    // Save as JSON (Aelia requirement)
    update_post_meta(
        $post_id,
        '_regular_currency_prices',
        wp_json_encode( $regular_prices_arr )
    );

    if ( ! empty( $sale_prices_arr ) ) {
        update_post_meta(
            $post_id,
            '_sale_currency_prices',
            wp_json_encode( $sale_prices_arr )
        );
    } else {
        delete_post_meta( $post_id, '_sale_currency_prices' );
    }
}

