/**
 * ---------------------------------------------------------------------
 * 1. ROLE SNAPSHOT STORAGE (PER REQUEST)
 * ---------------------------------------------------------------------
 */
function artmatter_get_role_snapshot( $user_id, $set_roles = null ) {
    static $snapshots = [];

    if ( $set_roles !== null && ! isset( $snapshots[ $user_id ] ) ) {
        $snapshots[ $user_id ] = (array) $set_roles;
    }

    return $snapshots[ $user_id ] ?? null;
}

/**
 * ---------------------------------------------------------------------
 * 2. SNAPSHOT TRIGGER (BEFORE ROLE DB WRITE)
 * ---------------------------------------------------------------------
 */
add_filter( 'update_user_metadata', function ( $check, $object_id, $meta_key ) {
    global $wpdb;

    if ( $meta_key === $wpdb->prefix . 'capabilities' || $meta_key === 'wp_capabilities' ) {
        $user = get_userdata( $object_id );
        if ( $user ) {
            artmatter_get_role_snapshot( $object_id, $user->roles );
        }
    }

    return $check;
}, 10, 3 );

/**
 * ---------------------------------------------------------------------
 * 3. META NOISE FILTER (SESSION / CART / WC ONLY)
 * ---------------------------------------------------------------------
 */
function artmatter_should_ignore_user_meta( $meta_key ) {

    // WooCommerce + session churn
    $ignored_prefixes = [
        '_woocommerce_persistent_cart_',
        'wc_',
        'session_',
    ];

    foreach ( $ignored_prefixes as $prefix ) {
        if ( str_starts_with( $meta_key, $prefix ) ) {
            return true;
        }
    }

    // Explicit noisy keys
    $ignored_keys = [
        'last_update',
        'paying_customer',
        'shipping_method',
        'billing_phone_formatted',
        'shipping_phone_formatted',
        'session_tokens',
    ];

    return in_array( $meta_key, $ignored_keys, true );
}

/**
 * ---------------------------------------------------------------------
 * 4. WEBHOOK DISPATCHER
 * ---------------------------------------------------------------------
 */
function artmatter_send_user_webhook( $user_id, $source = 'unknown' ) {

    // Debounce (2s)
    $lock_key = 'artmatter_user_webhook_' . $user_id;
    if ( get_transient( $lock_key ) ) {
        return;
    }
    set_transient( $lock_key, 1, 2 );

    $user = get_userdata( $user_id );
    if ( ! $user ) {
        return;
    }

    // Snapshot roles
    $snapshot_roles = artmatter_get_role_snapshot( $user_id );

    if ( $source === 'user_register' ) {
        $raw_old_roles = [];
    } else {
        $raw_old_roles = is_array( $snapshot_roles ) ? $snapshot_roles : $user->roles;
    }

    $old_roles = array_values( array_unique( array_filter( (array) $raw_old_roles ) ) );
    $new_roles = array_values( array_unique( array_filter( (array) $user->roles ) ) );

    /**
     * -------------------------------------------------------------
     * ROLE GATEKEEPER
     * -------------------------------------------------------------
     */
    $watched_roles = [ 'artist', 'artist_in_review', 'artist_rejected' ];

    $is_relevant_now = ! empty( array_intersect( $new_roles, $watched_roles ) );
    $was_relevant    = ! empty( array_intersect( $old_roles, $watched_roles ) );

    // Only send webhook if artist involved at any point
    if ( ! $is_relevant_now && ! $was_relevant ) {
        return;
    }

    /**
     * -------------------------------------------------------------
     * SEMANTIC EVENT DETECTION (ROLE-BASED)
     * -------------------------------------------------------------
     */
    $event = 'artist_updated';

    if ( $source === 'user_register' ) {
        if ( in_array( 'artist_in_review', $new_roles, true ) ) {
            $event = 'artist_applied';
        } elseif ( in_array( 'artist', $new_roles, true ) ) {
            $event = 'artist_registered';
        }
    }
    elseif ( in_array( 'artist_in_review', $old_roles, true ) && in_array( 'artist', $new_roles, true ) ) {
        $event = 'artist_approved';
    }
    elseif ( in_array( 'artist', $old_roles, true ) && in_array( 'artist_in_review', $new_roles, true ) ) {
        $event = 'artist_reverted';
    }
    elseif ( in_array( 'artist', $old_roles, true ) && ! in_array( 'artist', $new_roles, true ) ) {
        $event = 'artist_removed';
    }
    elseif ( in_array( 'artist_in_review', $old_roles, true ) && in_array( 'artist_rejected', $new_roles, true ) ) {
        $event = 'artist_rejected';
    }
    elseif ( array_diff( $old_roles, $new_roles ) || array_diff( $new_roles, $old_roles ) ) {
        $event = 'role_changed';
    }

    $updated_at = current_time( 'mysql' );

    $idempotency_key = md5(
        $user_id . '|' . $event . '|' . implode( ',', $new_roles ) . '|' . $updated_at
    );

    $payload = [
        'event'           => $event,
        'idempotency_key' => $idempotency_key,
        'user_id'         => $user_id,
        'source'          => $source,
        'user'            => [
            'data'      => $user->data,
            'roles'     => $new_roles,
            'old_roles' => $old_roles,
            'caps'      => $user->caps,
            'allcaps'   => $user->allcaps,
        ],
        'meta'       => get_user_meta( $user_id ),
        'acf'        => function_exists( 'get_fields' ) ? get_fields( 'user_' . $user_id ) : null,
        'updated_at' => $updated_at,
    ];

    wp_remote_post(
        'https://api.artmatter.co/webhook/artmatter/user/update',
        [
            'timeout' => 5,
            'headers' => [
                'Content-Type' => 'application/json',
                'x-secret-key' => 'YOUR_WEBHOOK_SECRET',
            ],
            'body' => wp_json_encode( $payload ),
        ]
    );
}

