/**
 * Secure Artist Phone OTP Verification (FINAL)
 * REST API + SMS / WhatsApp Webhook
 */

if ( ! defined( 'ABSPATH' ) ) exit;

class Artist_Phone_OTP {

    const NS = 'artist/v1';
    const WEBHOOK = 'https://api.artmatter.co/webhook/artmatter/pf/artist/verify/phone-otp-send';

    const OTP_EXPIRY = 600; // 10 minutes
    const BLOCK_TIME = 600; // 10 minutes
    const MAX_RESENDS  = 3;
    const MAX_ATTEMPTS = 5;

    public static function init() {
        add_action( 'rest_api_init', [ __CLASS__, 'routes' ] );
        add_action( 'wp_head', [ __CLASS__, 'inject_js_config' ] );
    }

    /* ---------------------------------------------------
     * Inject REST config for frontend
     * --------------------------------------------------- */
    public static function inject_js_config() {
        if ( ! is_user_logged_in() ) return;
        if ( ! is_page( 'dashboard' ) ) return;

        echo '<script>
            window.artistPhoneOtp = {
                root: "' . esc_url_raw( rest_url() ) . '",
                nonce: "' . wp_create_nonce( 'wp_rest' ) . '"
            };
        </script>';
    }

    /* ---------------------------------------------------
     * Routes
     * --------------------------------------------------- */
    public static function routes() {

        register_rest_route( self::NS, '/phone/send', [
            'methods'  => 'POST',
            'callback' => [ __CLASS__, 'send_otp' ],
            'permission_callback' => fn() => is_user_logged_in()
        ]);

        register_rest_route( self::NS, '/phone/verify', [
            'methods'  => 'POST',
            'callback' => [ __CLASS__, 'verify_otp' ],
            'permission_callback' => fn() => is_user_logged_in()
        ]);
    }

    /* ---------------------------------------------------
     * SEND OTP
     * --------------------------------------------------- */
    public static function send_otp( WP_REST_Request $req ) {

        $user_id = get_current_user_id();
        $phone   = self::normalize_phone( $req->get_param( 'phone' ) );

        if ( ! $phone ) {
            return new WP_Error( 'invalid_phone', 'Invalid phone number.', [ 'status' => 400 ] );
        }

        // Prevent duplicate phone usage (optional but recommended)
        $existing_user = $wpdb->get_var(
			$wpdb->prepare(
				"SELECT user_id FROM {$wpdb->usermeta}
				 WHERE meta_key = 'phone_number'
				 AND meta_value = %s
				 LIMIT 1",
				$phone
			)
		);

		if ( $existing_user && (int) $existing_user !== (int) $user_id ) {
			return new WP_Error(
				'phone_exists',
				'This phone number is already in use by another account.',
				['status' => 409]
			);
		}


        if ( self::is_blocked( $user_id ) ) {
            return new WP_Error( 'blocked', 'Too many attempts. Try again later.', [ 'status' => 403 ] );
        }

        $resends = (int) get_user_meta( $user_id, 'verify_phone_otp_resends', true );
        if ( $resends >= self::MAX_RESENDS ) {
            self::block( $user_id );
            return new WP_Error( 'blocked', 'Too many requests.', [ 'status' => 403 ] );
        }

        $otp = (string) rand( 100000, 999999 );

        update_user_meta( $user_id, 'verify_phone_pending', $phone );
        update_user_meta( $user_id, 'verify_phone_otp_hash', wp_hash_password( $otp ) );
        update_user_meta( $user_id, 'verify_phone_otp_expires', time() + self::OTP_EXPIRY );
        update_user_meta( $user_id, 'verify_phone_otp_attempts', 0 );
        update_user_meta( $user_id, 'verify_phone_otp_resends', $resends + 1 );
        update_user_meta( $user_id, 'verify_phone_status', 'pending' );

        $response = wp_remote_post( self::WEBHOOK, [
            'headers' => [ 'Content-Type' => 'application/json' ],
            'body' => json_encode([
                'artist_id' => $user_id,
                'phone'     => $phone,
                'otp'       => $otp
            ]),
            'timeout' => 8
        ]);

        if ( is_wp_error( $response ) || wp_remote_retrieve_response_code( $response ) !== 200 ) {
            return new WP_Error( 'send_fail', 'Failed to send OTP.', [ 'status' => 500 ] );
        }

        return rest_ensure_response([
            'success' => true,
            'message' => 'Verification code sent.'
        ]);
    }

    /* ---------------------------------------------------
     * VERIFY OTP
     * --------------------------------------------------- */
    public static function verify_otp( WP_REST_Request $req ) {

        $user_id = get_current_user_id();
        $code    = sanitize_text_field( $req->get_param( 'code' ) );

        if ( strlen( $code ) !== 6 ) {
            return new WP_Error( 'invalid_code', 'Enter the 6-digit code.', [ 'status' => 400 ] );
        }

        if ( self::is_blocked( $user_id ) ) {
            return new WP_Error( 'blocked', 'Verification temporarily blocked.', [ 'status' => 403 ] );
        }

        $expires = (int) get_user_meta( $user_id, 'verify_phone_otp_expires', true );
        if ( time() > $expires ) {
            return new WP_Error( 'expired', 'Code expired.', [ 'status' => 400 ] );
        }

        $hash = get_user_meta( $user_id, 'verify_phone_otp_hash', true );

        if ( ! wp_check_password( $code, $hash ) ) {
            $attempts = (int) get_user_meta( $user_id, 'verify_phone_otp_attempts', true );
            update_user_meta( $user_id, 'verify_phone_otp_attempts', $attempts + 1 );

            if ( $attempts + 1 >= self::MAX_ATTEMPTS ) {
                self::block( $user_id );
                return new WP_Error( 'blocked', 'Too many failed attempts.', [ 'status' => 403 ] );
            }

            return new WP_Error( 'invalid_code', 'Incorrect code.', [ 'status' => 400 ] );
        }

        // SUCCESS
        $phone = get_user_meta( $user_id, 'verify_phone_pending', true );

        if ( $phone ) {
            update_user_meta( $user_id, 'phone_number', $phone );
        }

        update_user_meta( $user_id, 'verify_phone_status', 'verified' );
        self::cleanup( $user_id );

        return rest_ensure_response([
            'success' => true,
            'message' => 'Phone number verified successfully.'
        ]);
    }

    /* ---------------------------------------------------
     * Helpers
     * --------------------------------------------------- */

    private static function normalize_phone( $raw ) {
        $raw = preg_replace( '/[^0-9+]/', '', $raw );
        if ( ! preg_match( '/^\+[1-9]\d{7,14}$/', $raw ) ) return false;
        return $raw;
    }

    private static function phone_exists( $phone ) {
        global $wpdb;
        return (bool) $wpdb->get_var(
            $wpdb->prepare(
                "SELECT user_id FROM {$wpdb->usermeta}
                 WHERE meta_key = 'phone_number'
                 AND meta_value = %s
                 LIMIT 1",
                $phone
            )
        );
    }

    private static function is_blocked( $uid ) {
        $until = (int) get_user_meta( $uid, 'verify_phone_blocked_until', true );
        if ( $until && time() < $until ) return true;
        if ( $until ) self::cleanup_counters( $uid );
        return false;
    }

    private static function block( $uid ) {
        update_user_meta( $uid, 'verify_phone_blocked_until', time() + self::BLOCK_TIME );
    }

    private static function cleanup( $uid ) {
        delete_user_meta( $uid, 'verify_phone_pending' );
        delete_user_meta( $uid, 'verify_phone_otp_hash' );
        delete_user_meta( $uid, 'verify_phone_otp_expires' );
        self::cleanup_counters( $uid );
    }

    private static function cleanup_counters( $uid ) {
        delete_user_meta( $uid, 'verify_phone_otp_attempts' );
        delete_user_meta( $uid, 'verify_phone_otp_resends' );
        delete_user_meta( $uid, 'verify_phone_blocked_until' );
    }
}

