add_filter( 'posts_search', 'bricks_fast_taxonomy_search', 500, 2 );

function bricks_fast_taxonomy_search( $search, $wp_query ) {
    // 1. Run only on frontend search
    if ( ! $wp_query->is_search() || is_admin() ) {
        return $search;
    }

    global $wpdb;
    $term = get_query_var( 's' );
    
    if ( empty( $term ) ) return $search;

    // 2. Prepare for Speed (Standard LIKE)
    $like = '%' . $wpdb->esc_like( $term ) . '%';
    $like = esc_sql( $like );

    // 3. Define Taxonomies
    // ADD 'product_tag' here so standard tags are included
    $taxonomies = array( 
        'product_tag',  // <--- Added standard WooCommerce Tags
        'art_fandom', 
        'art_subject', 
        'art_style', 
        'art_mood', 
        'art_color' 
    );
    
    $tax_list = "'" . implode( "','", $taxonomies ) . "'";

    // 4. Build the Query
    $search = " AND (
        -- Match Title
        ({$wpdb->posts}.post_title LIKE '{$like}')
        
        OR 
        
        -- Match Description (Content)
        ({$wpdb->posts}.post_content LIKE '{$like}')
        
        OR 
        
        -- Match Taxonomies (Fast Subquery)
        EXISTS (
            SELECT 1 
            FROM {$wpdb->term_relationships} AS tr
            INNER JOIN {$wpdb->term_taxonomy} AS tt ON tr.term_taxonomy_id = tt.term_taxonomy_id
            INNER JOIN {$wpdb->terms} AS t ON tt.term_id = t.term_id
            WHERE tr.object_id = {$wpdb->posts}.ID
            AND tt.taxonomy IN ({$tax_list})
            AND t.name LIKE '{$like}'
        )
    )";

    return $search;
}

/**
 * Plugin Name: ArtMatter Library Filter
 * Description: Hides 'Master' files (files with a linked public ID) from the WordPress Media Library grid and list views to prevent performance issues.
 */

// 1. Hide from GRID VIEW (The main media library popup/grid)
add_filter( 'ajax_query_attachments_args', 'artmatter_hide_masters_from_grid' );

function artmatter_hide_masters_from_grid( $query ) {
    // Only run in admin dashboard to be safe
    if ( ! is_admin() ) return $query;

    // Get current meta query or initialize empty array
    $meta_query = isset( $query['meta_query'] ) ? $query['meta_query'] : [];

    // EXCLUDE items that have the '_artmatter_public_attachment_id' key.
    // (Only Master files have this key set in your Processor code)
    $meta_query[] = [
        'key'     => '_artmatter_public_attachment_id',
        'compare' => 'NOT EXISTS',
    ];

    $query['meta_query'] = $meta_query;
    return $query;
}

// 2. Hide from LIST VIEW (The detailed table view in Media > Library)
add_action( 'pre_get_posts', 'artmatter_hide_masters_from_list' );

function artmatter_hide_masters_from_list( $query ) {
    // Only target the main admin query for attachments
    if ( is_admin() && $query->is_main_query() && $query->get('post_type') === 'attachment' ) {
        
        // Use the current screen to ensure we don't hide them 
        // if you are specifically looking for them in a custom tool
        $screen = get_current_screen();
        if ( ! $screen || 'upload' !== $screen->id ) return;

        $meta_query = $query->get('meta_query');
        if ( ! is_array( $meta_query ) ) $meta_query = [];

        // Same logic: If it points to a public ID, it is a master, so hide it.
        $meta_query[] = [
            'key'     => '_artmatter_public_attachment_id',
            'compare' => 'NOT EXISTS',
        ];

        $query->set( 'meta_query', $meta_query );
    }
}

/**
 * Webhook Trigger: New Fandom Created
 * Sends ID, Title, Slug, Description, and ACF fields to n8n/Node.
 */
add_action( 'saved_art_fandom', 'artmatter_trigger_fandom_webhook', 50, 3 );

function artmatter_trigger_fandom_webhook( $term_id, $tt_id, $update ) {
    
    // 1. CHECK: Only run for NEW terms (ignore updates)
    if ( $update ) {
        return;
    }

    // 2. GET DATA: Retrieve standard term data
    $term = get_term( $term_id, 'art_fandom' );
    
    if ( ! $term || is_wp_error( $term ) ) {
        return;
    }

    // 3. GET ACF: Retrieve all custom fields for this term
    // Note: ACF stores term data with the prefix 'term_{ID}'
    $acf_fields = get_fields( 'term_' . $term_id );

    // 4. PREPARE PAYLOAD
    $payload = [
        'id'      => $term_id,
        'title'   => $term->name,
        'slug'    => $term->slug,
        'content' => $term->description, // Term 'content' is usually the Description field
        'acf'     => $acf_fields ?: [],  // Send empty array if no ACF data found
    ];

    // 5. SEND WEBHOOK
    // blocking = false ensures the user doesn't wait for the webhook to finish loading
    wp_remote_post( 'https://api.artmatter.co/webhook/artmatter/wp/fandom', [
        'headers'   => [ 'Content-Type' => 'application/json', 'x-secret-key'  => 'YOUR_WEBHOOK_SECRET', ],
        'body'      => json_encode( $payload ),
        'blocking'  => false, 
        'sslverify' => true,
    ]);
}

/**
 * Artmatter – Custom Product Statuses (Clean & Complete)
 *
 * ✔ Registers custom product statuses
 * ✔ Shows them in the status dropdown
 * ✔ Displays correct label in Publish metabox
 * ✔ Blocks public access (404) - FIXED
 * ✔ Does NOT interfere with REST / n8n / save logic
 */

if ( ! defined( 'ABSPATH' ) ) exit;

class Artmatter_Product_Statuses {

    const STATUSES = [
        'rejected'      => 'Rejected',
        'sched_removal' => 'Scheduled for Removal',
    ];

    public static function init() {
        add_action( 'init', [ self::class, 'register_statuses' ] );
        add_filter( 'wc_product_statuses', [ self::class, 'add_to_wc_statuses' ] );
        add_filter( 'display_post_states', [ self::class, 'display_status_label' ], 10, 2 );
        
        // CHANGED: Switched from 'pre_get_posts' to 'template_redirect' to fix memory leak
        add_action( 'template_redirect', [ self::class, 'block_public_access' ] );
        
        add_action( 'admin_footer', [ self::class, 'inject_status_dropdown_options' ] );
    }

    /**
     * Register custom post statuses
     */
    public static function register_statuses() {
        foreach ( self::STATUSES as $slug => $label ) {
            register_post_status( $slug, [
                'label'                     => $label,
                'public'                    => false,
                'exclude_from_search'       => true,
                'show_in_admin_all_list'    => true,
                'show_in_admin_status_list' => true,
                'show_in_rest'              => true,
                /* Fixed logic for singular/plural count */
                'label_count'               => _n_noop(
                    "{$label} <span class='count'>(%s)</span>",
                    "{$label} <span class='count'>(%s)</span>"
                ),
            ] );
        }
    }

    /**
     * Make WooCommerce aware of the statuses
     */
    public static function add_to_wc_statuses( $statuses ) {
        foreach ( self::STATUSES as $slug => $label ) {
            $statuses[ $slug ] = $label;
        }
        return $statuses;
    }

    /**
     * Show label inside "Status:" line in Publish metabox
     */
    public static function display_status_label( $states, $post ) {

        if ( $post->post_type !== 'product' ) {
            return $states;
        }

        if ( isset( self::STATUSES[ $post->post_status ] ) ) {
            $states[ $post->post_status ] = self::STATUSES[ $post->post_status ];
        }

        return $states;
    }

    /**
     * Inject custom statuses into the Status dropdown (admin UI only)
     */
    public static function inject_status_dropdown_options() {
        global $post;

        if ( ! $post || $post->post_type !== 'product' ) {
            return;
        }
        ?>
        <script>
        jQuery(function($){
            const statuses = <?php echo wp_json_encode( self::STATUSES ); ?>;
            const $select  = $('#post_status');

            if (!$select.length) return;

            Object.entries(statuses).forEach(([value, label]) => {
                if ($select.find('option[value="'+value+'"]').length === 0) {
                    $select.append(
                        $('<option>', { value, text: label })
                    );
                }
            });
        });
        </script>
        <?php
    }

    /**
     * Block public access for custom statuses
     * FIXED: Now runs on template_redirect to avoid infinite loop
     */
    public static function block_public_access() {

        // 1. Basic checks
        if ( is_admin() || ! is_singular( 'product' ) ) {
            return;
        }

        // 2. Get the current post object (Safe to do in template_redirect)
        $post = get_queried_object();

        // 3. Security Check
        if (
            $post &&
            isset( self::STATUSES[ $post->post_status ] ) &&
            ! current_user_can( 'edit_products' )
        ) {
            global $wp_query;
            $wp_query->set_404();
            status_header( 404 );
            nocache_headers();
        }
    }
}

