/**
 * Simple & Robust n8n Webhook (Bulk Edit Compatible)
 * Runs on 'shutdown' to ensure all data is saved.
 * Handles single edits, bulk edits, and API updates.
 */

// Initialize a global array to store ALL modified IDs
if ( ! isset( $GLOBALS['n8n_product_sync_ids'] ) ) {
    $GLOBALS['n8n_product_sync_ids'] = [];
}

// 1. Queue the IDs on Save
add_action( 'save_post_product', function( $post_id ) {
    if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return;
    if ( wp_is_post_revision( $post_id ) ) return;
    
    // Append the ID to our list (Using [] to add to array)
    $GLOBALS['n8n_product_sync_ids'][] = $post_id;
}, 10, 1 );

// 2. Fire the Webhooks at the very end
add_action( 'shutdown', function() {
    
    // Check if we have any IDs to sync
    if ( empty( $GLOBALS['n8n_product_sync_ids'] ) ) return;

    // Remove duplicates (save_post sometimes fires twice for the same ID)
    $unique_ids = array_unique( $GLOBALS['n8n_product_sync_ids'] );

    // Loop through EACH product and send data
    foreach ( $unique_ids as $post_id ) {
        
        // Force Fresh Data
        clean_post_cache( $post_id );

        $post = get_post( $post_id );
        
        // Safety check if post still exists
        if ( ! $post ) continue; 

        $image_id = get_post_thumbnail_id( $post_id );

        // Build Payload
        $payload = [
            'product_id'    => $post_id,
            'title'         => $post->post_title,
            'slug'          => $post->post_name,
            'status'        => $post->post_status,
            'created_at'    => $post->post_date,
            'updated_at'    => current_time( 'mysql' ),
            'product_url'   => get_permalink( $post_id ),
            
            // Visuals
            'image_id'      => $image_id,
            'image_url'     => $image_id ? wp_get_attachment_url( $image_id ) : null,

            // Terms & Taxonomies
            'taxonomies'    => get_post_taxonomies( $post_id ), 
            'terms'         => wp_get_post_terms( $post_id, get_post_taxonomies( $post_id ) ),

            // Meta Data
            'meta'          => get_post_meta( $post_id ),
        ];

        // Send to n8n (Fire & Forget for each product)
        wp_remote_post( 'https://api.artmatter.co/webhook/artmatter/wp/product', [
            'body'      => json_encode( $payload ),
            'headers'   => [ 
                'Content-Type' => 'application/json', 
                'x-secret-key' => 'YOUR_WEBHOOK_SECRET', 
            ],
            'timeout'   => 5,
            'blocking'  => false, 
            'sslverify' => true,
        ]);
    }
});

