        return;
    }

    $username = sanitize_user( wp_unslash( $_GET['r'] ) );
    $user     = get_user_by( 'login', $username );

    if (
        ! $user ||
        ! in_array( 'artist', (array) $user->roles, true )
    ) {
        return;
    }

    $referral = [
        'program'            => 'share_and_earn',
        'referrer_id'        => (int) $user->ID,
        'referrer_username'  => $user->user_login,
        'captured_at'        => time(),
        'expires_at'         => time() + ( DAY_IN_SECONDS * 30 ),
    ];

    // Persist (cookie)
    setcookie(
        'artmatter_referral',
        wp_json_encode( $referral ),
        $referral['expires_at'],
        COOKIEPATH,
        COOKIE_DOMAIN,
        is_ssl(),
        true
    );

    // Persist (session)
    if ( function_exists( 'WC' ) && WC()->session ) {
        WC()->session->set( 'artmatter_referral', $referral );
    }
});


add_action( 'woocommerce_before_checkout_process', function () {

    if ( ! function_exists( 'WC' ) || ! WC()->session ) {
        return;
    }

    if ( WC()->session->get( 'artmatter_referral' ) ) {
        return;
    }

    if ( empty( $_COOKIE['artmatter_referral'] ) ) {
        return;
    }

    $referral = json_decode( wp_unslash( $_COOKIE['artmatter_referral'] ), true );

    if (
        empty( $referral['referrer_id'] ) ||
        empty( $referral['expires_at'] ) ||
        time() > (int) $referral['expires_at']
    ) {
