/**
 * ============================================================
 * Artmatter – Robust Order Sync (Action Scheduler Edition)
 * ============================================================
 * - Handles order create/update/status change
 * - Debounced background sync
 * - Includes Advanced Coupons shipping discounts (fees)
 */

// ============================================================
// 1. TRIGGERS
// ============================================================

add_action( 'woocommerce_new_order', 'artmatter_queue_order_sync', 10, 1 );
add_action( 'woocommerce_update_order', 'artmatter_queue_order_sync', 10, 1 );
add_action( 'woocommerce_order_status_changed', 'artmatter_queue_order_sync', 10, 1 );
add_action( 'woocommerce_saved_order_items', 'artmatter_queue_order_sync', 10, 2 );

function artmatter_queue_order_sync( $order_id ) {

    if ( ! function_exists( 'as_schedule_single_action' ) ) {
        return;
    }

    $order_id = (int) $order_id;
    if ( ! $order_id ) return;

    // Debounce: prevent duplicate scheduled jobs
    if ( as_has_scheduled_action( 'artmatter_n8n_sync_job', [ 'order_id' => $order_id ] ) ) {
        return;
    }

    // Delay allows all plugins (Advanced Coupons, shipping, etc) to finish
    as_schedule_single_action(
        time() + 5,
        'artmatter_n8n_sync_job',
        [ 'order_id' => $order_id ],
        'artmatter-webhooks'
    );
}

// ============================================================
// 2. WORKER (Background Job)
// ============================================================

add_action( 'artmatter_n8n_sync_job', 'artmatter_execute_n8n_send', 10, 1 );

function artmatter_execute_n8n_send( $order_id ) {

    $order = wc_get_order( $order_id );
    if ( ! $order ) return;

    $logger      = wc_get_logger();
    $log_context = [ 'source' => 'artmatter-n8n' ];

    // ========================================================
    // ORDER META
    // ========================================================

    $meta_data = [];
    foreach ( $order->get_meta_data() as $meta ) {
        $meta_data[ $meta->key ] = $meta->value;
    }

    // ========================================================
    // LINE ITEMS
    // ========================================================

    $items = [];
    foreach ( $order->get_items() as $item_id => $item ) {

        $item_meta = [];
        foreach ( $item->get_meta_data() as $im ) {
            $item_meta[ $im->key ] = $im->value;
        }

        $product = $item->get_product();

        $items[] = [
            'order_item_id' => (int) $item_id,
            'product_id'    => (int) $item->get_product_id(),
            'variation_id'  => (int) $item->get_variation_id(),
            'name'          => $item->get_name(),
            'quantity'      => (int) $item->get_quantity(),
            'total'         => (float) $item->get_total(),
            'sku'           => $product ? $product->get_sku() : '',
            'meta'          => $item_meta,
        ];
    }

    // ========================================================
    // FEES (IMPORTANT: Shipping discounts live here)
    // ========================================================

    $fees       = [];
    $fees_total = 0.0;

    foreach ( $order->get_fees() as $fee_id => $fee ) {

        $amount = (float) $fee->get_total();
        $name   = $fee->get_name();

        $is_shipping_discount = stripos( $name, 'shipping' ) !== false;

        $fees[] = [
            'fee_id' => (int) $fee_id,
            'name'   => $name,
            'total'  => $amount,
            'tax'    => (float) $fee->get_total_tax(),
            'type'   => $is_shipping_discount ? 'shipping_discount' : 'fee',
        ];

        $fees_total += $amount;
    }

    // ========================================================
    // PAYLOAD
    // ========================================================

    $payload = [
        'order_id'     => $order_id,
        'order_number' => $order->get_order_number(),
        'status'       => $order->get_status(),
        'currency'     => $order->get_currency(),
        'created_at'   => $order->get_date_created() ? $order->get_date_created()->date( 'c' ) : null,
        'updated_at'   => $order->get_date_modified() ? $order->get_date_modified()->date( 'c' ) : null,

        'totals' => [
            'subtotal'   => (float) $order->get_subtotal(),
            'shipping'   => (float) $order->get_shipping_total(),
            'discount'   => (float) $order->get_discount_total(), // coupons only
            'fees_total' => (float) $fees_total,                  // includes shipping discount
            'total'      => (float) $order->get_total(),
        ],

        'fees'     => $fees,
        'items'    => $items,

        'customer' => [
            'id'    => (int) $order->get_customer_id(),
            'email' => $order->get_billing_email(),
            'phone' => $order->get_billing_phone(),
            'note'  => $order->get_customer_note(),
        ],

        'billing'  => $order->get_address( 'billing' ),
        'shipping' => $order->get_address( 'shipping' ),
        'meta'     => $meta_data,
    ];

    // ========================================================
    // SEND TO N8N
    // ========================================================

    $response = wp_remote_post(
        'https://api.artmatter.co/webhook/artmatter/wp/order',
        [
            'body'      => wp_json_encode( $payload ),
            'headers'   => [
                'Content-Type' => 'application/json',
                'x-secret-key' => 'YOUR_WEBHOOK_SECRET',
            ],
            'timeout'   => 15,
            'blocking'  => true,
            'sslverify' => true,
        ]
    );

    // ========================================================
    // LOGGING & RETRIES
    // ========================================================

    if ( is_wp_error( $response ) ) {
        $logger->error(
            "Order #{$order_id} sync failed: " . $response->get_error_message(),
            $log_context
        );

        // Trigger Action Scheduler retry
        throw new Exception( $response->get_error_message() );
    }

    $status = wp_remote_retrieve_response_code( $response );

    if ( $status >= 200 && $status < 300 ) {
        $logger->info(
            "Order #{$order_id} sync success (HTTP {$status})",
            $log_context
        );
    } else {
        $logger->error(
            "Order #{$order_id} sync rejected (HTTP {$status})",
            $log_context
        );
    }
}

/**
 * Optimized Artwork Counter
 * Uses direct SQL for zero-memory impact.
 */
function artmatter_recalculate_artist_artwork_counts( int $user_id ): void {
    if ( ! $user_id ) return;

    global $wpdb;

    // DIRECT SQL: Lightest possible way to count. 
    // Does not load posts into memory.
    $published = $wpdb->get_var( $wpdb->prepare(
        "SELECT COUNT(ID) FROM {$wpdb->posts} 
         WHERE post_type = 'product' 
         AND post_status = 'publish' 
         AND post_author = %d",
        $user_id
    ) );

    $pending = $wpdb->get_var( $wpdb->prepare(
        "SELECT COUNT(ID) FROM {$wpdb->posts} 
         WHERE post_type = 'product' 
         AND post_status = 'pending' 
         AND post_author = %d",
        $user_id
    ) );

    update_user_meta( $user_id, 'artist_artwork_published', (int) $published );
    update_user_meta( $user_id, 'artist_artwork_pending',   (int) $pending );
}

