/**
 * Trigger 1: When an artwork changes status (e.g., Pending -> Publish, or moved to Trash)
 */
add_action( 'transition_post_status', function( $new_status, $old_status, $post ) {
    if ( $post->post_type !== 'product' || $new_status === $old_status ) {
        return;
    }
    
    artmatter_recalculate_artist_artwork_counts( (int) $post->post_author );
}, 10, 3 );

/**
 * Trigger 2: When an artwork's author is reassigned
 */
add_action( 'post_updated', function( $post_ID, $post_after, $post_before ) {
    if ( $post_after->post_type !== 'product' ) {
        return;
    }
    
    // If the artist was changed, update BOTH the old artist and the new artist
    if ( $post_after->post_author != $post_before->post_author ) {
        artmatter_recalculate_artist_artwork_counts( (int) $post_before->post_author );
        artmatter_recalculate_artist_artwork_counts( (int) $post_after->post_author );
    }
}, 10, 3 );

/**
 * Trigger 3: When an artwork is permanently deleted
 */
add_action( 'deleted_post', function( $post_id, $post ) {
    if ( $post->post_type === 'product' ) {
        artmatter_recalculate_artist_artwork_counts( (int) $post->post_author );
    }
}, 10, 2 );

function artmatter_get_carrier_tracking_url( $carrier, $tracking_number ) {
	if ( ! $carrier || ! $tracking_number ) {
		return '';
	}

	$tracking_number = rawurlencode( $tracking_number );

	$carriers = [
		'jne'     => 'https://www.jne.co.id/',
		'sicepat' => 'https://www.sicepat.com',
		'pos'     => 'https://www.posindonesia.co.id/en/tracking/?tracknumbers=%s',
		'goorita' => 'https://send.goorita.com/track',
	];

	$carrier_key = strtolower( $carrier );

	if ( ! isset( $carriers[ $carrier_key ] ) ) {
		return '';
	}

	return sprintf( $carriers[ $carrier_key ], $tracking_number );
}

