/**
 * Log Tracking Changes to Order Notes (Fixed Caching Issue)
 */

// Global variable to temporarily store the OLD state
$artmatter_old_tracking_state = [];

// 1. Capture OLD value BEFORE save (Priority 1)
add_action( 'acf/save_post', 'artmatter_capture_old_tracking', 1 );
function artmatter_capture_old_tracking( $post_id ) {
    // Only run on shop orders
    if ( get_post_type( $post_id ) !== 'shop_order' ) {
        return;
    }

    global $artmatter_old_tracking_state;

    // We use get_post_meta() to get the raw DB value
    $artmatter_old_tracking_state[ $post_id ] = [
        'tracking' => get_post_meta( $post_id, 'tracking_number', true ),
        'carrier'  => get_post_meta( $post_id, 'carrier_id', true ),
    ];
}

// 2. Capture NEW value AFTER save & Compare (Priority 20)
add_action( 'acf/save_post', 'artmatter_log_tracking_changes', 20 );
function artmatter_log_tracking_changes( $post_id ) {
    
    // Only run on shop orders
    if ( get_post_type( $post_id ) !== 'shop_order' ) {
        return;
    }

    global $artmatter_old_tracking_state;

    // Retrieve the OLD data we saved in step 1
    $old_data = isset( $artmatter_old_tracking_state[ $post_id ] ) ? $artmatter_old_tracking_state[ $post_id ] : [];
    $old_tracking = isset( $old_data['tracking'] ) ? trim( $old_data['tracking'] ) : '';

    // Retrieve the NEW data directly from DB (Bypassing ACF Cache)
    $new_tracking = trim( get_post_meta( $post_id, 'tracking_number', true ) );
    $new_carrier  = get_post_meta( $post_id, 'carrier_id', true );

    // If the tracking number hasn't changed, stop here.
    if ( $old_tracking === $new_tracking ) {
        return;
    }

    // Get the Order object to add the note
    $order = wc_get_order( $post_id );
    if ( ! $order ) return;

    // Get nice carrier Label
    $carriers = [
        'jne'     => 'JNE',
        'sicepat' => 'Sicepat',
        'pos'     => 'POS Indonesia',
        'goorita' => 'Goorita'
    ];
    $carrier_label = isset( $carriers[ $new_carrier ] ) ? $carriers[ $new_carrier ] : ucfirst( $new_carrier );

    // --- LOGIC TO ADD NOTE ---

    if ( empty( $old_tracking ) && ! empty( $new_tracking ) ) {
        // Case: Added New
        $note = sprintf( 'Shipping: Tracking number added <strong>%s</strong> (%s)', $new_tracking, $carrier_label );
        $order->add_order_note( $note );

    } elseif ( ! empty( $old_tracking ) && ! empty( $new_tracking ) ) {
        // Case: Updated
        $note = sprintf( 'Shipping: Tracking updated from "%s" to <strong>"%s"</strong> (%s)', $old_tracking, $new_tracking, $carrier_label );
        $order->add_order_note( $note );

    } elseif ( ! empty( $old_tracking ) && empty( $new_tracking ) ) {
        // Case: Removed
        $order->add_order_note( 'Shipping: Tracking number removed.' );
    }
}

