add_filter( 'bricks/form/validate', function ( $errors ) {

    $field = 'form-field-signup-invite-code';

    if ( ! isset( $_POST[ $field ] ) ) {
        return $errors;
    }

    $code = strtoupper( trim( $_POST[ $field ] ) );

    if ( empty( $code ) ) {
        $errors[ $field ] = 'Invite code is required.';
        return $errors;
    }

    global $wpdb;
    $table = $wpdb->prefix . 'artist_invites';

    $valid = $wpdb->get_var(
        $wpdb->prepare(
            "SELECT COUNT(*) FROM $table
             WHERE code = %s
               AND status = 'active'
               AND used_count < max_uses",
            $code
        )
    );

    if ( ! $valid ) {
        $errors[ $field ] = 'Invalid or expired invite code.';
    }

    return $errors;

}, 1 );


