 * ========================================================= */
add_action( 'user_register', function ( $user_id ) {

    $field = 'form-field-signup-invite-code';
    if ( empty( $_POST[ $field ] ) ) return;

    $code = strtoupper( trim( $_POST[ $field ] ) );
    if ( ! $code ) return;

    update_user_meta( $user_id, 'invite_code_used', $code );

    global $wpdb;
    $invites = $wpdb->prefix . 'artist_invites';
    $uses    = $wpdb->prefix . 'artist_invite_uses';

    $invite = $wpdb->get_row(
        $wpdb->prepare( "SELECT * FROM $invites WHERE code = %s", $code )
    );

    if ( ! $invite ) return;

    $wpdb->query(
        $wpdb->prepare(
            "UPDATE $invites SET used_count = used_count + 1 WHERE id = %d",
            $invite->id
        )
    );

    $user = get_userdata( $user_id );

    $wpdb->insert(
        $uses,
        [
            'invite_id' => $invite->id,
            'user_id'   => $user_id,
            'username'  => $user ? $user->user_login : null
        ]
    );
