/**
 * Secure Artist Email OTP Verification (FINAL)
 * REST API + N8N Webhook
 */

if ( ! defined( 'ABSPATH' ) ) exit;

class Artist_Email_OTP {

    const NS = 'artist/v1';
    const WEBHOOK = 'https://api.artmatter.co/webhook/artmatter/pf/artist/verify/email-otp-send';

    const OTP_EXPIRY = 900; // 15 minutes
    const BLOCK_TIME = 300; // 5 minutes
    const MAX_RESENDS  = 5;
    const MAX_ATTEMPTS = 5;

    public static function init() {
        add_action( 'rest_api_init', [ __CLASS__, 'routes' ] );
        add_action( 'wp_head', [ __CLASS__, 'inject_js_config' ] );
    }

    /* ---------------------------------------------------
     * Inject REST info for frontend JS
     * --------------------------------------------------- */
    public static function inject_js_config() {
        if ( ! is_user_logged_in() ) return;
        if ( ! is_page( 'dashboard' ) ) return;

        echo '<script>
            window.artistEmailOtp = {
                root: "' . esc_url_raw( rest_url() ) . '",
                nonce: "' . wp_create_nonce( 'wp_rest' ) . '"
            };
        </script>';
    }

    /* ---------------------------------------------------
     * Routes
     * --------------------------------------------------- */
    public static function routes() {

        register_rest_route( self::NS, '/send', [
            'methods'  => 'POST',
            'callback' => [ __CLASS__, 'send_otp' ],
            'permission_callback' => fn() => is_user_logged_in()
        ]);

        register_rest_route( self::NS, '/verify', [
            'methods'  => 'POST',
            'callback' => [ __CLASS__, 'verify_otp' ],
            'permission_callback' => fn() => is_user_logged_in()
        ]);
    }

    /* ---------------------------------------------------
     * SEND OTP
     * --------------------------------------------------- */
    public static function send_otp( WP_REST_Request $req ) {

        $user_id = get_current_user_id();
        $email   = sanitize_email( $req->get_param( 'email' ) );

        if ( ! is_email( $email ) ) {
            return new WP_Error( 'invalid_email', 'Invalid email address.', [ 'status' => 400 ] );
        }

        $current_user_id = get_current_user_id();
		$owner_id = email_exists( $email );

		// If email exists AND it does NOT belong to current user → block
		if ( $owner_id && (int) $owner_id !== (int) $current_user_id ) {
			return new WP_Error(
				'email_exists',
				'This email is already in use by another account.',
				['status' => 409]
			);
		}

        if ( self::is_blocked( $user_id ) ) {
            return new WP_Error( 'blocked', 'Too many attempts. Try again later.', [ 'status' => 403 ] );
        }

        $resends = (int) get_user_meta( $user_id, 'verify_email_otp_resends', true );
        if ( $resends >= self::MAX_RESENDS ) {
            self::block( $user_id );
            return new WP_Error( 'blocked', 'Too many requests.', [ 'status' => 403 ] );
        }

        $otp = (string) rand( 100000, 999999 );

        update_user_meta( $user_id, 'verify_email_pending', $email );
        update_user_meta( $user_id, 'verify_email_otp_hash', wp_hash_password( $otp ) );
        update_user_meta( $user_id, 'verify_email_otp_expires', time() + self::OTP_EXPIRY );
        update_user_meta( $user_id, 'verify_email_otp_attempts', 0 );
        update_user_meta( $user_id, 'verify_email_otp_resends', $resends + 1 );
        update_user_meta( $user_id, 'verify_email_status', 'pending' );

        $user = get_userdata( $user_id );

        $response = wp_remote_post( self::WEBHOOK, [
            'headers' => [ 'Content-Type' => 'application/json' ],
            'body' => json_encode([
                'artist_id' => $user_id,
                'email'     => $email,
                'name'      => $user->display_name,
                'otp'       => $otp
            ]),
            'timeout' => 8
        ]);

        if ( is_wp_error( $response ) || wp_remote_retrieve_response_code( $response ) !== 200 ) {
            return new WP_Error( 'send_fail', 'Failed to send email.', [ 'status' => 500 ] );
        }

        return rest_ensure_response([
            'success' => true,
            'message' => 'Verification code sent.'
        ]);
    }

    /* ---------------------------------------------------
     * VERIFY OTP
     * --------------------------------------------------- */
    public static function verify_otp( WP_REST_Request $req ) {

        $user_id = get_current_user_id();
        $code    = sanitize_text_field( $req->get_param( 'code' ) );

        if ( strlen( $code ) !== 6 ) {
            return new WP_Error( 'invalid_code', 'Enter the 6-digit code.', [ 'status' => 400 ] );
        }

        if ( self::is_blocked( $user_id ) ) {
            return new WP_Error( 'blocked', 'Verification temporarily blocked.', [ 'status' => 403 ] );
        }

        $expires = (int) get_user_meta( $user_id, 'verify_email_otp_expires', true );
        if ( time() > $expires ) {
            return new WP_Error( 'expired', 'Code expired.', [ 'status' => 400 ] );
        }

        $hash = get_user_meta( $user_id, 'verify_email_otp_hash', true );

        if ( ! wp_check_password( $code, $hash ) ) {
            $attempts = (int) get_user_meta( $user_id, 'verify_email_otp_attempts', true );
            update_user_meta( $user_id, 'verify_email_otp_attempts', $attempts + 1 );

            if ( $attempts + 1 >= self::MAX_ATTEMPTS ) {
                self::block( $user_id );
                return new WP_Error( 'blocked', 'Too many failed attempts.', [ 'status' => 403 ] );
            }

            return new WP_Error( 'invalid_code', 'Incorrect code.', [ 'status' => 400 ] );
        }

        // SUCCESS
        $new_email = get_user_meta( $user_id, 'verify_email_pending', true );

        if ( $new_email && is_email( $new_email ) ) {
            wp_update_user([
                'ID'         => $user_id,
                'user_email' => $new_email
            ]);
        }

        update_user_meta( $user_id, 'verify_email_status', 'verified' );
        self::cleanup( $user_id );

        return rest_ensure_response([
            'success' => true,
            'message' => 'Email verified successfully.'
        ]);
    }

    /* ---------------------------------------------------
     * Helpers
     * --------------------------------------------------- */
    private static function is_blocked( $uid ) {
        $until = (int) get_user_meta( $uid, 'verify_email_blocked_until', true );
        if ( $until && time() < $until ) return true;
        if ( $until ) self::cleanup_counters( $uid );
        return false;
    }

    private static function block( $uid ) {
        update_user_meta( $uid, 'verify_email_blocked_until', time() + self::BLOCK_TIME );
    }

    private static function cleanup( $uid ) {
        delete_user_meta( $uid, 'verify_email_pending' );
        delete_user_meta( $uid, 'verify_email_otp_hash' );
        delete_user_meta( $uid, 'verify_email_otp_expires' );
        self::cleanup_counters( $uid );
    }

    private static function cleanup_counters( $uid ) {
        delete_user_meta( $uid, 'verify_email_otp_attempts' );
        delete_user_meta( $uid, 'verify_email_otp_resends' );
        delete_user_meta( $uid, 'verify_email_blocked_until' );
    }
}

