/**
 * Snippet Name: Disable Checkout for IDR Currency on Overseas Shipments
 * Description: On the CheckoutWC page, this disables all "Continue" buttons and shows a notice if the selected country is not Indonesia and the currency is IDR.
 */

/**
 * Injects a self-contained JavaScript block into the footer of the checkout page.
 * This script handles the real-time validation of the selected country against the store's currency.
 */
function artmatter_checkout_currency_validation_script() {
    
    // 1. Only run this script on the WooCommerce checkout page.
    if ( ! function_exists('is_checkout') || ! is_checkout() || is_wc_endpoint_url() ) {
        return;
    }

    // 2. Get the current currency from WooCommerce to pass it to our JavaScript.
    $current_currency = get_woocommerce_currency();

    // 3. Use HEREDOC syntax to print the entire JavaScript block.
    ?>
    <script id="artmatter-currency-country-validator">
    jQuery(function($) {

        // Get the currency that was passed from PHP.
        const storeCurrency = '<?php echo esc_js( $current_currency ); ?>';

        // Add some basic CSS to make the disabled button and links non-clickable.
        const style = '<style>.artmatter-btn-disabled { pointer-events: none !important; opacity: 0.65 !important; }</style>';
        $('head').append(style);

        // Define the HTML for our warning message.
        const noticeHTML = '<div id="artmatter-currency-notice" class="woocommerce-error" style="display:none; margin: 0.5em 0px; font-size: 14px; border-radius: var(--radius-md); text-align: center; padding: var(--padding-sm); border: 1px solid var(--red-lt) !important; background-color: var(--red-dk) !important;}">IDR is not available for international shipping. Please switch to a supported currency to continue.</div>';
        
        // Cache our frequently used jQuery elements for performance.
        const $billingCountry = $('#billing_country');
        
        // --- CORRECTED NOTICE LOCATION ---
        // We will insert the notice *before* the address fields container.
        const $noticeContainer = $('#cfw-customer-info-action'); 
        
        // Cache all buttons and links that allow the user to proceed.
        const $continueButtons = $('.cfw-continue-to-shipping-btn, .cfw-continue-to-payment-btn, #place_order');
        const $breadcrumbLinks = $('#cfw-breadcrumb .tab a').not('[href="#cfw-customer-info"]'); // Exclude the link to the current tab.

        // Add the notice to the page (it's hidden by default).
        if( $noticeContainer.length > 0 && $('#artmatter-currency-notice').length === 0 ) {
             $noticeContainer.before(noticeHTML);
        }
        const $currencyNotice = $('#artmatter-currency-notice');

        /**
         * The core validation function. Checks the rule and updates the UI.
         */
        function validateCurrencyAndCountry() {
            const selectedCountry = $billingCountry.val();

            // The main condition: Is a country selected, is it NOT Indonesia, and is the currency IDR?
            if ( selectedCountry && selectedCountry !== 'ID' && storeCurrency === 'IDR' ) {
                // If the condition is met, show the notice and disable all forward navigation.
                $currencyNotice.show();
                $continueButtons.addClass('artmatter-btn-disabled');
                $breadcrumbLinks.addClass('artmatter-btn-disabled');
            } else {
                // Otherwise, hide the notice and enable navigation.
                $currencyNotice.hide();
                // IMPORTANT: We only remove our class, so we don't interfere with the Biteship script's validation.
                $continueButtons.removeClass('artmatter-btn-disabled'); 
                $breadcrumbLinks.removeClass('artmatter-btn-disabled');
            }
        }

        // --- Event Listeners ---

        // Run the check whenever the country field is changed by the user.
        // We use 'change input' to catch all types of changes.
        $(document.body).on('change input', '#billing_country', validateCurrencyAndCountry);
        
        // Run the check after WooCommerce updates the checkout. This is crucial.
        $(document.body).on('updated_checkout', validateCurrencyAndCountry);

        // Run the check on the initial page load, after a brief delay to ensure CFW has initialized.
        setTimeout(validateCurrencyAndCountry, 100);
    });
    </script>
    <?php
}

