add_action('wp_footer', function () {
    if (is_admin() || !is_checkout() || is_order_received_page()) return;

    $cart = WC()->cart;
    if (!$cart) return;

    $items = [];

    foreach ($cart->get_cart() as $cart_item) {
        $product = $cart_item['data'];
        if (!$product instanceof WC_Product) continue;

        $items[] = [
            'item_id'   => $product->get_sku() ?: $product->get_id(),
            'item_name' => $product->get_name(),
            'price'     => (float) $product->get_price(),
            'quantity'  => (int) $cart_item['quantity'],
        ];
    }
    ?>
    <script>
    (function () {
        if (window.__rybbit_begin_checkout_sent) return;

        const data = {
            currency: "<?php echo esc_js(get_woocommerce_currency()); ?>",
            value: <?php echo (float) $cart->get_total('edit'); ?>,
            items: <?php echo wp_json_encode($items); ?>
        };

        // Force numeric values (important)
        data.value = Number(data.value);
        data.items = data.items.map(i => ({
            ...i,
            price: Number(i.price),
            quantity: Number(i.quantity)
        }));

        const t = setInterval(() => {
            if (window.rybbit) {
                clearInterval(t);
                window.__rybbit_begin_checkout_sent = true;
                window.rybbit.event('begin_checkout', data);
            }
        }, 100);
    })();
    </script>
    <?php
});



