/**
 * Artmatter DB TRUTH FINDER
 * Finds exactly where a file key is mentioned in the database.
 */
add_action('admin_menu', function() {
    add_options_page('Truth Finder', 'Truth Finder', 'manage_options', 'artmatter-truth', 'artmatter_render_truth_finder');
});

function artmatter_render_truth_finder() {
    if (!current_user_can('manage_options')) return;

    global $wpdb;
    $search_key = isset($_POST['search_key']) ? sanitize_text_field($_POST['search_key']) : 'cliffside-blue-noon-master.jpg';

    echo '<div class="wrap"><h1>Database Truth Finder</h1>';
    echo '<form method="post"><p>Enter file name (e.g. <code>cliffside-blue-noon-master.jpg</code>):</p>';
    echo '<input type="text" name="search_key" value="'.esc_attr($search_key).'" style="width:400px;"> ';
    echo '<button class="button button-primary">Search Database</button></form><hr>';

    if ($_POST) {
        // Search for the key in postmeta
        $results = $wpdb->get_results($wpdb->prepare(
            "SELECT post_id, meta_key, meta_value FROM {$wpdb->postmeta} WHERE meta_value LIKE %s",
            '%' . $wpdb->esc_like($search_key) . '%'
        ));

        if ($results) {
            echo "<h3>Matches found for: <code>$search_key</code></h3>";
            echo '<table class="wp-list-table widefat fixed striped"><thead><tr><th>Post ID</th><th>Meta Key</th><th>Value in DB</th><th>Post Type</th></tr></thead><tbody>';
            foreach ($results as $row) {
                $post_type = get_post_type($row->post_id);
                $title = get_the_title($row->post_id);
                echo "<tr>
                    <td><strong>#{$row->post_id}</strong> ($title)</td>
                    <td><code>{$row->meta_key}</code></td>
                    <td><code>{$row->meta_value}</code></td>
                    <td>$post_type</td>
                </tr>";
            }
            echo '</tbody></table>';
        } else {
            echo '<div class="notice notice-error"><p>Zero results found. WordPress does NOT know about this file.</p></div>';
            echo '<p>If you see this error, then the <strong>Purge Tool</strong> should definitely be listing it as an orphan.</p>';
        }
    }
    echo '</div>';
}

