// 3. Handle the Upload & Replacement Logic (Admin Only)
add_action('save_post_product', function($post_id) {
    // Security & Role Checks
    if (!current_user_can('administrator')) return;
    if (!isset($_POST['artmatter_nonce']) || !wp_verify_nonce($_POST['artmatter_nonce'], 'artmatter_swap_nonce')) return;
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) return;
    if (empty($_FILES['artmatter_new_master']['name'])) return;

    require_once(ABSPATH . 'wp-admin/includes/file.php');
    require_once(ABSPATH . 'wp-admin/includes/image.php');

    $file = $_FILES['artmatter_new_master'];
    $upload = wp_handle_upload($file, ['test_form' => false]);

    if (isset($upload['file'])) {
        $local_new_path = $upload['file'];
        $product = get_post($post_id);
        $thumb_id = get_post_thumbnail_id($post_id);
        
        // 1. Determine Target Artist Slug
        $terms = get_the_terms($post_id, 'artwork_artist') ?: get_the_terms($post_id, 'artist');
        $artist_slug = ($terms && !is_wp_error($terms)) ? $terms[0]->slug : 'uncategorized';
        
        // 2. Prepare Naming (Strict ID Format)
        $clean_slug = sanitize_title($product->post_title);
        $ext = pathinfo($local_new_path, PATHINFO_EXTENSION);
        $new_filename = "{$clean_slug}-{$post_id}-master.{$ext}";
        $new_r2_key = "arts-master/artists/{$artist_slug}/{$new_filename}";

        // 3. Delete OLD file from R2
        $master_id = get_post_meta($thumb_id, '_artmatter_master_attachment_id', true);
        if ($master_id) {
            $old_r2_key = get_post_meta($master_id, '_artmatter_r2_key', true);
            if ($old_r2_key && class_exists('Artmatter_R2')) {
                Artmatter_R2::delete_file($old_r2_key);
            }
        } else {
            $attachment_data = [
                'post_mime_type' => $upload['type'],
                'post_title'     => $product->post_title . ' - Master',
                'post_status'    => 'inherit',
            ];
            $master_id = wp_insert_attachment($attachment_data, $local_new_path);
            update_post_meta($thumb_id, '_artmatter_master_attachment_id', $master_id);
        }

        // 4. Upload NEW file to R2
        if (class_exists('Artmatter_R2')) {
            if (Artmatter_R2::upload_file($local_new_path, $new_r2_key)) {
                update_post_meta($master_id, '_artmatter_r2_key', $new_r2_key);
                update_post_meta($master_id, '_artmatter_r2_synced', true);
                update_post_meta($master_id, '_wp_attached_file', $new_r2_key);
                @unlink($local_new_path);
            }
        }
    }
});

add_action('init', function () {

    // 🔐 Only allow admins
    if (!current_user_can('administrator')) return;

    // 🔗 Trigger: ?rml_fix=15279
    if (!isset($_GET['rml_fix'])) return;

    $attachment_id = intval($_GET['rml_fix']);

    if (!$attachment_id) {
        echo 'Invalid attachment ID';
        exit;
    }

    // 🔁 Reset flags
    delete_post_meta($attachment_id, '_rml_synced_final');
    delete_post_meta($attachment_id, '_rml_master_worker_scheduled');

    // 🔁 Run resync
    if (function_exists('rml_force_resync_attachment')) {
        rml_force_resync_attachment($attachment_id);
    }

    echo "RML resync triggered for attachment ID: {$attachment_id}";
    exit;
});

add_filter( 'bricks/maintenance/should_apply', function( $apply_maintenance, $mode ) {
    // Get the current full URL requested by the visitor
    $current_url = home_url( $_SERVER['REQUEST_URI'] );

    // Check if the current URL starts with the specified path
    if ( strpos( $current_url, 'https://artmatter.co/posters/custom' ) === 0 ) {
        return false; // False tells Bricks to BYPASS maintenance mode
    }

    // Otherwise, keep the default maintenance mode behavior
    return $apply_maintenance;
}, 10, 2 );
